\9\9if deletions == nil then\
\9\9\9returnFiber.deletions = { childToDelete }\
\9\9\9returnFiber.flags = bit32.bor(returnFiber.flags, Deletion)\
\9\9else\
\9\9\9table.insert(deletions, childToDelete)\
\9\9end\
\9end\
