\9\9\9-- throwOnInvalidObjectType(returnFiber, newChild)\
\9\9end\
\
\9\9if typeOfNewChild == \"string\" or typeOfNewChild == \"number\" then\
\9\9\9-- Text nodes don't have keys. If the previous node is implicitly keyed\
\9\9\9-- we can continue to replace it without aborting even if it is not a text\
\9\9\9-- node.\
\9\9\9local created =\
\9\9\9\9createFiberFromText(tostring(newChild), returnFiber.mode, lanes)\
\9\9\9created.return_ = returnFiber\
\9\9\9return created\
\9\9end\
\
\9\9if __DEV__ then\
\9\9\9if typeOfNewChild == \"function\" then\
\9\9\9\9warnOnFunctionType(returnFiber)\
\9\9\9end\
\9\9end\
\
\9\9return nil\
\9end\
\
\9local function updateSlot(\
\9\9returnFiber: Fiber,\
\9\9oldFiber: Fiber | nil,\
\9\9newChild: any,\
\9\9lanes: Lanes,\
\9\9-- ROBLOX deviation: children table key for compat with Roact's stable keys\
\9\9tableKey: any?\
\9): Fiber | nil\
\9\9-- ROBLOX performance: early exit for nil newChild since no actions will be taken\
\9\9if newChild == nil then\
\9\9\9return nil\
\9\9end\
\
\9\9-- Update the fiber if the keys match, otherwise return nil.\
\
\9\9local key = if oldFiber ~= nil then oldFiber.key else nil\
\9\9-- ROBLOX performance: avoid repeated calls to typeof since Luau doesn't cache\
\9\9local typeOfNewChild = type(newChild)\
\
\9\9if typeOfNewChild == \"table\" then\
\9\9\9-- ROBLOX deviation: Roact stable keys - forward children table key to\
\9\9\9-- child if applicable\
\9\9\9assignStableKey(tableKey, newChild)\
\9\9\9-- ROBLOX performance: avoid repeated indexing to $$typeof\
\9\9\9local newChildTypeof = newChild[\"$$typeof\"]\
\9\9\9if newChildTypeof == REACT_ELEMENT_TYPE then\
\9\9\9\9if newChild.key == key then\
\9\9\9\9\9if newChild.type == REACT_FRAGMENT_TYPE then\
\9\9\9\9\9\9return updateFragment(\
\9\9\9\9\9\9\9returnFiber,\
\9\9\9\9\9\9\9oldFiber,\
\9\9\9\9\9\9\9newChild.props.children,\
\9\9\9\9\9\9\9lanes,\
\9\9\9\9\9\9\9key :: string?\
\9\9\9\9\9\9)\
\9\9\9\9\9end\
\9\9\9\9\9return updateElement(returnFiber, oldFiber, newChild, lanes)\
\9\9\9\9else\
\9\9\9\9\9return nil\
\9\9\9\9end\
\9\9\9elseif newChildTypeof == REACT_PORTAL_TYPE then\
\9\9\9\9if newChild.key == key then\
\9\9\9\9\9return updatePortal(returnFiber, oldFiber, newChild, lanes)\
\9\9\9\9else\
\9\9\9\9\9return nil\
\9\9\9\9end\
\9\9\9elseif newChildTypeof == REACT_LAZY_TYPE then\
\9\9\9\9if enableLazyElements then\
\9\9\9\9\9local payload = newChild._payload\
\9\9\9\9\9local init = newChild._init\
\9\9\9\9\9-- ROBLOX deviation: Roact stable keys - Since the table key was\
\9\9\9\9\9-- already applied to `newChild` above, we don't need to pass it along\
\9\9\9\9\9return updateSlot(returnFiber, oldFiber, init(payload), lanes)\
\9\9\9\9end\
\9\9\9end\
\
\9\9\9-- ROBLOX deviation peformance: this is the equiv of checking for a table, and we already know typeof(newChild) is a table in this branch\
\9\9\9-- if isArray(newChild) or getIteratorFn(newChild) then\
\9\9\9if key ~= nil then\
\9\9\9\9return nil\
\9\9\9end\
\
\9\9\9return updateFragment(returnFiber, oldFiber, newChild, lanes)\
\
\9\9\9-- ROBLOX performance deviation: unreachable with the above table check\
\9\9\9-- throwOnInvalidObjectType(returnFiber, newChild)\
\9\9end\
\
\9\9-- ROBLOX performance: do this compare last to save 2 string cmp in typical Roblox hot path\
\9\9if typeOfNewChild == \"string\" or typeOfNewChild == \"number\" then\
\9\9\9-- Text nodes don't have keys. If the previous node is implicitly keyed\
\9\9\9-- we can continue to replace it without aborting even if it is not a text\
\9\9\9-- node.\
\9\9\9if key ~= nil then\
\9\9\9\9return nil\
\9\9\9end\
\9\9\9return updateTextNode(returnFiber, oldFiber, tostring(newChild), lanes)\
\9\9end\
\
\9\9if __DEV__ then\
\9\9\9if typeOfNewChild == \"function\" then\
\9\9\9\9warnOnFunctionType(returnFiber)\
\9\9\9end\
\9\9end\
\
\9\9return nil\
\9end\
\
\9local function updateFromMap(\
\9\9existingChildren: Map<string | number, Fiber>,\
\9\9returnFiber: Fiber,\
\9\9newIdx: number,\
\9\9newChild: any,\
\9\9lanes: Lanes,\
\9\9-- ROBLOX deviation: children table key for compat with Roact's stable keys\
\9\9tableKey: any?\
\9): Fiber | nil\
\9\9-- ROBLOX performance: early exit for nil newChild since no actions will be taken\
\9\9if newChild == nil then\
\9\9\9return nil\
\9\9end\
\
\9\9-- ROBLOX performance: avoid repeated calls to typeof since Luau doesn't cache\
\9\9local typeOfNewChild = type(newChild)\
\
\9\9if typeOfNewChild == \"table\" then\
\9\9\9-- ROBLOX deviation: Roact stable keys - forward children table key to\
\9\9\9-- child if applicable\
\9\9\9assignStableKey(tableKey, newChild)\
\9\9\9local existingChildrenKey\
\9\9\9-- ROBLOX performance: avoid repeated indexing to $$typeof\
\9\9\9local newChildTypeof = newChild[\"$$typeof\"]\
\9\9\9if newChildTypeof == REACT_ELEMENT_TYPE then\
\9\9\9\9if newChild.key == nil then\
\9\9\9\9\9existingChildrenKey = newIdx\
\9\9\9\9else\
\9\9\9\9\9existingChildrenKey = newChild.key\
\9\9\9\9end\
\9\9\9\9local matchedFiber = existingChildren[existingChildrenKey]\
\9\9\9\9if newChild.type == REACT_FRAGMENT_TYPE then\
\9\9\9\9\9return updateFragment(\
\9\9\9\9\9\9returnFiber,\
\9\9\9\9\9\9matchedFiber,\
\9\9\9\9\9\9newChild.props.children,\
\9\9\9\9\9\9lanes,\
\9\9\9\9\9\9newChild.key\
\9\9\9\9\9)\
\9\9\9\9end\
\9\9\9\9return updateElement(returnFiber, matchedFiber, newChild, lanes)\
\9\9\9elseif newChildTypeof == REACT_PORTAL_TYPE then\
\9\9\9\9if newChild.key == nil then\
\9\9\9\9\9existingChildrenKey = newIdx\
\9\9\9\9else\
\9\9\9\9\9existingChildrenKey = newChild.key\
\9\9\9\9end\
\9\9\9\9local matchedFiber = existingChildren[existingChildrenKey]\
\9\9\9\9return updatePortal(returnFiber, matchedFiber, newChild, lanes)\
\9\9\9elseif newChildTypeof == REACT_LAZY_TYPE then\
\9\9\9\9if enableLazyElements then\
\9\9\9\9\9local payload = newChild._payload\
\9\9\9\9\9local init = newChild._init\
\9\9\9\9\9-- ROBLOX deviation: Roact stable keys - Since the table key was\
\9\9\9\9\9-- already applied to `newChild` above, we don't need to pass it along\
\9\9\9\9\9return updateFromMap(\
\9\9\9\9\9\9existingChildren,\
\9\9\9\9\9\9returnFiber,\
\9\9\9\9\9\9newIdx,\
\9\9\9\9\9\9init(payload),\
\9\9\9\9\9\9lanes\
\9\9\9\9\9)\
\9\9\9\9end\
\9\9\9end\
\
\9\9\9-- ROBLOX deviation peformance: this is the equiv of checking for a table, and we already know typeof(newChild) is a table in this branch\
\9\9\9-- if isArray(newChild) or getIteratorFn(newChild) then\
\9\9\9local matchedFiber = existingChildren[newIdx]\
\9\9\9return updateFragment(returnFiber, matchedFiber, newChild, lanes)\
\
\9\9\9-- ROBLOX performance deviation: unreachable with the above table check\
\9\9\9-- throwOnInvalidObjectType(returnFiber, newChild)\
\9\9end\
\
\9\9-- ROBLOX performance: do this compare last, as Roblox won't really support text nodes directly\
\9\9if typeOfNewChild == \"string\" or typeOfNewChild == \"number\" then\
\9\9\9-- Text nodes don't have keys, so we neither have to check the old nor\
\9\9\9-- new node for the key. If both are text nodes, they match.\
\9\9\9local matchedFiber = existingChildren[newIdx] or nil\
\9\9\9return updateTextNode(returnFiber, matchedFiber, tostring(newChild), lanes)\
\9\9end\
\
\9\9if __DEV__ then\
\9\9\9if typeOfNewChild == \"function\" then\
\9\9\9\9warnOnFunctionType(returnFiber)\
\9\9\9end\
\9\9end\
\
\9\9return nil\
\9end\
\
\9--[[\
\9Warns if there is a duplicate or missing key\
  ]]\
\9local function warnOnInvalidKey(\
\9\9child: any,\
\9\9knownKeys: Set<string> | nil,\
\9\9returnFiber: Fiber\
\9): Set<string> | nil\
\9\9if __DEV__ then\
\9\9\9if child == nil or type(child) ~= \"table\" then\
\9\9\9\9return knownKeys\
\9\9\9end\
\9\9\9-- ROBLOX performance: avoid repeated indexing to $$typeof\
\9\9\9local childTypeof = child[\"$$typeof\"]\
\9\9\9if childTypeof == REACT_ELEMENT_TYPE or childTypeof == REACT_PORTAL_TYPE then\
\9\9\9\9warnForMissingKey(child, returnFiber)\
\9\9\9\9local key = child.key\
\9\9\9\9if type(key) ~= \"string\" then\
\9\9\9\9\9-- break\
\9\9\9\9elseif knownKeys == nil then\
\9\9\9\9\9knownKeys = {};\
\9\9\9\9\9(knownKeys :: Set<string>)[key] = true\
\9\9\9\9elseif not (knownKeys :: Set<string>)[key] then\
\9\9\9\9\9(knownKeys :: Set<string>)[key] = true\
\9\9\9\9else\
\9\9\9\9\9console.error(\
\9\9\9\9\9\9\"Encountered two children with the same key, `%s`. \"\
\9\9\9\9\9\9\9.. \"Keys should be unique so that components maintain their identity \"\
\9\9\9\9\9\9\9.. \"across updates. Non-unique keys may cause children to be \"\
\9\9\9\9\9\9\9.. \"duplicated and/or omitted — the behavior is unsupported and \"\
\9\9\9\9\9\9\9.. \"could change in a future version.\",\
\9\9\9\9\9\9key\
\9\9\9\9\9)\
\9\9\9\9end\
\9\9\9elseif childTypeof == REACT_LAZY_TYPE then\
\9\9\9\9if enableLazyElements then\
\9\9\9\9\9local payload = child._payload\
\9\9\9\9\9local init = child._init\
\9\9\9\9\9warnOnInvalidKey(init(payload), knownKeys, returnFiber)\
\9\9\9\9end\
\9\9\9end\
\9\9end\
\9\9return knownKeys\
\9end\
\
\9local function reconcileChildrenArray(\
\9\9returnFiber: Fiber,\
\9\9currentFirstChild: Fiber | nil,\
\9\9newChildren: Array<any>,\
\9\9lanes: Lanes\
\9): Fiber | nil\
\9\9-- This algorithm can't optimize by searching from both ends since we\
\9\9-- don't have backpointers on fibers. I'm trying to see how far we can get\
\9\9-- with that model. If it ends up not being worth the tradeoffs, we can\
\9\9-- add it later.\
\
\9\9-- Even with a two ended optimization, we'd want to optimize for the case\
\9\9-- where there are few changes and brute force the comparison instead of\
\9\9-- going for the Map. It'd like to explore hitting that path first in\
\9\9-- forward-only mode and only go for the Map once we notice that we need\
\9\9-- lots of look ahead. This doesn't handle reversal as well as two ended\
\9\9-- search but that's unusual. Besides, for the two ended optimization to\
\9\9-- work on Iterables, we'd need to copy the whole set.\
\
\9\9-- In this first iteration, we'll just live with hitting the bad case\
\9\9-- (adding everything to a Map) in for every insert/move.\
\
\9\9-- If you change this code, also update reconcileChildrenIterator() which\
\9\9-- uses the same algorithm.\
\
\9\9if __DEV__ then\
\9\9\9-- First, validate keys.\
\9\9\9local knownKeys = nil\
\9\9\9for i, child in newChildren do\
\9\9\9\9knownKeys = warnOnInvalidKey(child, knownKeys, returnFiber)\
\9\9\9end\
\9\9end\
\
\9\9local resultingFirstChild: Fiber | nil = nil\
\9\9local previousNewFiber: Fiber | nil = nil\
\
\9\9local oldFiber: Fiber | nil = currentFirstChild\
\9\9local lastPlacedIndex = 1\
\9\9local newIdx = 1\
\9\9local nextOldFiber: Fiber | nil = nil\
\9\9-- ROBLOX performance: don't re-evaluate length of newChildren on each iteration through the loop\
\9\9local newChildrenCount = #newChildren\
\9\9-- ROBLOX deviation: use while loop in place of modified for loop\
\9\9while oldFiber ~= nil and newIdx <= newChildrenCount do\
\9\9\9if oldFiber.index > newIdx then\
\9\9\9\9nextOldFiber = oldFiber\
\9\9\9\9oldFiber = nil\
\9\9\9else\
\9\9\9\9nextOldFiber = oldFiber.sibling\
\9\9\9end\
\9\9\9--[[\
\9\9\9\9ROBLOX DEVIATION: We pass newIdx to createChild to ensure that children are\
\9\9\9\9assigned a key, assuming the child is not an array itself. We only need to\
\9\9\9\9pass newIdx if the child is actually a React element. If the child is a\
\9\9\9\9string or number, a key is never assigned, so we do not pass newIdx as a key.\
\9\9\9]]\
\9\9\9local newFiber\
\9\9\9-- ROBLOX performance: avoid repeated indexing of newChildren to newIdx\
\9\9\9local newChildNewIdx = newChildren[newIdx]\
\9\9\9if\
\9\9\9\9newChildNewIdx ~= nil\
\9\9\9\9and type(newChildNewIdx) == \"table\"\
\9\9\9\9and newChildNewIdx[\"$$typeof\"] ~= nil\
\9\9\9then\
\9\9\9\9newFiber =\
\9\9\9\9\9updateSlot(returnFiber, oldFiber, newChildNewIdx, lanes, newIdx)\
\9\9\9else\
\9\9\9\9newFiber = updateSlot(returnFiber, oldFiber, newChildNewIdx, lanes)\
\9\9\9end\
\9\9\9if newFiber == nil then\
\9\9\9\9-- TODO: This breaks on empty slots like nil children. That's\
\9\9\9\9-- unfortunate because it triggers the slow path all the time. We need\
\9\9\9\9-- a better way to communicate whether this was a miss or nil,\
\9\9\9\9-- boolean, undefined, etc.\
\9\9\9\9if oldFiber == nil then\
\9\9\9\9\9oldFiber = nextOldFiber\
\9\9\9\9end\
\9\9\9\9break\
\9\9\9end\
\9\9\9if shouldTrackSideEffects then\
\9\9\9\9-- ROBLOX FIXME Luau: needs type states to understand the continue above\
\9\9\9\9if oldFiber and (newFiber :: Fiber).alternate == nil then\
\9\9\9\9\9-- We matched the slot, but we didn't reuse the existing fiber, so we\
\9\9\9\9\9-- need to delete the existing child.\
\9\9\9\9\9-- ROBLOX FIXME Luau: needs type states to understand the break above\
\9\9\9\9\9deleteChild(returnFiber, oldFiber :: Fiber)\
\9\9\9\9end\
\9\9\9end\
\9\9\9lastPlacedIndex = placeChild(newFiber :: Fiber, lastPlacedIndex, newIdx)\
\9\9\9if previousNewFiber == nil then\
\9\9\9\9-- TODO: Move out of the loop. This only happens for the first run.\
\9\9\9\9resultingFirstChild = newFiber\
\9\9\9else\
\9\9\9\9-- TODO: Defer siblings if we're not at the right index for this slot.\
\9\9\9\9-- I.e. if we had nil values before, then we want to defer this\
\9\9\9\9-- for each nil value. However, we also don't want to call updateSlot\
\9\9\9\9-- with the previous one.\
\9\9\9\9(previousNewFiber :: Fiber).sibling = newFiber\
\9\9\9end\
\9\9\9previousNewFiber = newFiber\
\9\9\9oldFiber = nextOldFiber\
\9\9\9-- deviation: increment manually since we're not using a modified for loop\
\9\9\9newIdx += 1\
\9\9end\
\
\9\9if newIdx > newChildrenCount then\
\9\9\9-- We've reached the end of the new children. We can delete the rest.\
\9\9\9deleteRemainingChildren(returnFiber, oldFiber)\
\9\9\9return resultingFirstChild\
\9\9end\
\
\9\9if oldFiber == nil then\
\9\9\9-- If we don't have any more existing children we can choose a fast path\
\9\9\9-- since the rest will all be insertions.\
\9\9\9-- deviation: use while loop in place of modified for loop\
\9\9\9while newIdx <= newChildrenCount do\
\9\9\9\9--[[\
\9\9\9\9\9ROBLOX DEVIATION: We pass newIdx to createChild to ensure that children are\
\9\9\9\9\9assigned a key, assuming the child is not an array itself. We only need to\
\9\9\9\9\9pass newIdx if the child is actually a React element. If the child is a\
\9\9\9\9\9string or number, a key is never assigned, so we do not pass newIdx as a key.\
\9\9\9\9]]\
\9\9\9\9local newFiber\
\9\9\9\9-- ROBLOX performance: avoid repeated indexing of newChildren to newIdx\
\9\9\9\9local newChildNewIdx = newChildren[newIdx]\
\9\9\9\9if\
\9\9\9\9\9newChildNewIdx ~= nil\
\9\9\9\9\9and type(newChildNewIdx) == \"table\"\
\9\9\9\9\9and newChildNewIdx[\"$$typeof\"] ~= nil\
\9\9\9\9then\
\9\9\9\9\9newFiber = createChild(returnFiber, newChildNewIdx, lanes, newIdx)\
\9\9\9\9else\
\9\9\9\9\9newFiber = createChild(returnFiber, newChildNewIdx, lanes)\
\9\9\9\9end\
\9\9\9\9if newFiber == nil then\
\9\9\9\9\9-- ROBLOX deviation: increment manually since we're not using a modified for loop\
\9\9\9\9\9newIdx += 1\
\9\9\9\9\9continue\
\9\9\9\9end\
\9\9\9\9-- ROBLOX FIXME Luau: needs type state to understand the continue above\
\9\9\9\9lastPlacedIndex = placeChild(newFiber :: Fiber, lastPlacedIndex, newIdx)\
\9\9\9\9if previousNewFiber == nil then\
\9\9\9\9\9-- TODO: Move out of the loop. This only happens for the first run.\
\9\9\9\9\9resultingFirstChild = newFiber\
\9\9\9\9else\
\9\9\9\9\9(previousNewFiber :: Fiber).sibling = newFiber\
\9\9\9\9end\
\9\9\9\9previousNewFiber = newFiber\
\9\9\9\9-- deviation: increment manually since we're not using a modified for loop\
\9\9\9\9newIdx += 1\
\9\9\9end\
\9\9\9return resultingFirstChild\
\9\9end\
\
\9\9-- Add all children to a key map for quick lookups.\
\9\9-- ROBLOX FIXME Luau: need type state to understand the if/return above\
\9\9local existingChildren = mapRemainingChildren(returnFiber, oldFiber :: Fiber)\
\
\9\9-- Keep scanning and use the map to restore deleted items as moves.\
\9\9-- ROBLOX deviation: use while loop in place of modified for loop\
\9\9while newIdx <= newChildrenCount do\
\9\9\9local newFiber\
\9\9\9-- ROBLOX performance: avoid repeated indexing of newChildren to newIdx\
\9\9\9local newChildNewIdx = newChildren[newIdx]\
\9\9\9if\
\9\9\9\9not FFlagReactPreventAssigningKeyToChildren\
\9\9\9\9or (\
\9\9\9\9\9newChildNewIdx ~= nil\
\9\9\9\9\9and type(newChildNewIdx) == \"table\"\
\9\9\9\9\9and newChildNewIdx[\"$$typeof\"] ~= nil\
\9\9\9\9)\
\9\9\9then\
\9\9\9\9newFiber = updateFromMap(\
\9\9\9\9\9existingChildren,\
\9\9\9\9\9returnFiber,\
\9\9\9\9\9newIdx,\
\9\9\9\9\9newChildNewIdx,\
\9\9\9\9\9lanes,\
\9\9\9\9\9-- ROBLOX deviation: pass newIdx to be used as the key of the element\
\9\9\9\9\9newIdx\
\9\9\9\9)\
\9\9\9else\
\9\9\9\9newFiber = updateFromMap(\
\9\9\9\9\9existingChildren,\
\9\9\9\9\9returnFiber,\
\9\9\9\9\9newIdx,\
\9\9\9\9\9newChildNewIdx,\
\9\9\9\9\9lanes\
\9\9\9\9)\
\9\9\9end\
\9\9\9if newFiber ~= nil then\
\9\9\9\9if shouldTrackSideEffects then\
\9\9\9\9\9if newFiber.alternate ~= nil then\
\9\9\9\9\9\9-- The new fiber is a work in progress, but if there exists a\
\9\9\9\9\9\9-- current, that means that we reused the fiber. We need to delete\
\9\9\9\9\9\9-- it from the child list so that we don't add it to the deletion\
\9\9\9\9\9\9-- list.\
\9\9\9\9\9\9existingChildren[if newFiber.key == nil\
\9\9\9\9\9\9\9then newIdx\
\9\9\9\9\9\9\9else newFiber.key] =\
\9\9\9\9\9\9\9nil\
\9\9\9\9\9end\
\9\9\9\9end\
\9\9\9\9lastPlacedIndex = placeChild(newFiber, lastPlacedIndex, newIdx)\
\9\9\9\9if previousNewFiber == nil then\
\9\9\9\9\9resultingFirstChild = newFiber\
\9\9\9\9else\
\9\9\9\9\9(previousNewFiber :: Fiber).sibling = newFiber\
\9\9\9\9end\
\9\9\9\9previousNewFiber = newFiber\
\9\9\9end\
\9\9\9-- deviation: increment manually since we're not using a modified for loop\
\9\9\9newIdx += 1\
\9\9end\
\
\9\9if shouldTrackSideEffects then\
\9\9\9-- Any existing children that weren't consumed above were deleted. We need\
\9\9\9-- to add them to the deletion list.\
\9\9\9for _, child in existingChildren do\
\9\9\9\9deleteChild(returnFiber, child)\
\9\9\9end\
\9\9end\
\
\9\9return resultingFirstChild\
\9end\
\
\9-- ROBLOX TODO: LUAFDN-254\
\9local function reconcileChildrenIterator(\
\9\9returnFiber: Fiber,\
\9\9currentFirstChild: Fiber | nil,\
\9\9-- ROBLOX TODO: figure out our Iterable<> interface\
