\9local function reconcileSingleTextNode(\
\9\9returnFiber: Fiber,\
\9\9currentFirstChild: Fiber | nil,\
\9\9textContent: string,\
\9\9lanes: Lanes\
\9): Fiber\
\9\9-- There's no need to check for keys on text nodes since we don't have a\
\9\9-- way to define them.\
\9\9-- ROBLOX FIXME: Luau narrowing issue\
\9\9if currentFirstChild ~= nil and (currentFirstChild :: Fiber).tag == HostText then\
\9\9\9-- We already have an existing node so let's just update it and delete\
\9\9\9-- the rest.\
\9\9\9deleteRemainingChildren(returnFiber, (currentFirstChild :: Fiber).sibling)\
\9\9\9local existing = useFiber(currentFirstChild :: Fiber, textContent)\
\9\9\9existing.return_ = returnFiber\
\9\9\9return existing\
\9\9end\
\9\9-- The existing first child is not a text node so we need to create one\
\9\9-- and delete the existing ones.\
\9\9deleteRemainingChildren(returnFiber, currentFirstChild)\
\9\9local created = createFiberFromText(textContent, returnFiber.mode, lanes)\
\9\9created.return_ = returnFiber\
\9\9return created\
\9end\
