\9\9local child = currentFirstChild\
\9\9while child ~= nil do\
\9\9\9-- TODO: If key == nil and child.key == nil, then this only applies to\
\9\9\9-- the first item in the list.\
\9\9\9if child.key == key then\
\9\9\9\9if\
\9\9\9\9\9child.tag == HostPortal\
\9\9\9\9\9and child.stateNode.containerInfo == portal.containerInfo\
\9\9\9\9\9and child.stateNode.implementation == portal.implementation\
\9\9\9\9then\
\9\9\9\9\9deleteRemainingChildren(returnFiber, child.sibling)\
\9\9\9\9\9local existing = useFiber(child, portal.children or {})\
\9\9\9\9\9existing.return_ = returnFiber\
\9\9\9\9\9return existing\
\9\9\9\9else\
\9\9\9\9\9deleteRemainingChildren(returnFiber, child)\
\9\9\9\9\9break\
\9\9\9\9end\
\9\9\9else\
\9\9\9\9deleteChild(returnFiber, child)\
\9\9\9end\
\9\9\9child = child.sibling\
\9\9end\
\
\9\9local created = createFiberFromPortal(portal, returnFiber.mode, lanes)\
\9\9created.return_ = returnFiber\
\9\9return created\
\9end\
