\9\9\9workInProgress.child = current.child\
\9\9end\
\9\9workInProgress.memoizedProps = current.memoizedProps\
\9\9if current.memoizedState ~= nil or workInProgress.memoizedState ~= nil then\
\9\9\9workInProgress.memoizedState = current.memoizedState\
\9\9end\
\9\9if current.updateQueue ~= nil or workInProgress.updateQueue ~= nil then\
\9\9\9workInProgress.updateQueue = current.updateQueue\
\9\9end\
\
\9\9local currentDependencies = current.dependencies\
\9\9if currentDependencies == nil then\
\9\9\9if workInProgress.dependencies ~= nil then\
\9\9\9\9workInProgress.dependencies = nil\
\9\9\9end\
\9\9else\
\9\9\9workInProgress.dependencies = {\
\9\9\9\9lanes = currentDependencies.lanes,\
\9\9\9\9firstContext = currentDependencies.firstContext,\
\9\9\9}\
\9\9end\
\
\9\9if current.sibling ~= nil or workInProgress.sibling ~= nil then\
\9\9\9workInProgress.sibling = current.sibling\
\9\9end\
\9\9workInProgress.index = current.index\
\9\9if current.ref ~= nil or workInProgress.ref ~= nil then\
\9\9\9workInProgress.ref = current.ref\
\9\9end\
\9else\
\9\9workInProgress.child = current.child\
\9\9workInProgress.memoizedProps = current.memoizedProps\
\9\9workInProgress.memoizedState = current.memoizedState\
\9\9workInProgress.updateQueue = current.updateQueue\
\
\9\9-- Clone the dependencies object. This is mutated during the render phase, so\
\9\9-- it cannot be shared with the current fiber.\
\9\9local currentDependencies = current.dependencies\
\9\9if currentDependencies == nil then\
\9\9\9workInProgress.dependencies = nil\
\9\9else\
\9\9\9workInProgress.dependencies = {\
\9\9\9\9lanes = currentDependencies.lanes,\
\9\9\9\9firstContext = currentDependencies.firstContext,\
\9\9\9}\
\9\9end\
\
\9\9-- These will be overridden during the parent's reconciliation\
\9\9workInProgress.sibling = current.sibling\
\9\9workInProgress.index = current.index\
\9\9workInProgress.ref = current.ref\
\9end\
\
\9if enableProfilerTimer then\
\9\9workInProgress.selfBaseDuration = current.selfBaseDuration\
\9\9workInProgress.treeBaseDuration = current.treeBaseDuration\
\9end\
\
\9if __DEV__ then\
\9\9workInProgress._debugNeedsRemount = current._debugNeedsRemount\
\9\9if\
\9\9\9workInProgress.tag == IndeterminateComponent\
\9\9\9or workInProgress.tag == FunctionComponent\
\9\9\9or workInProgress.tag == SimpleMemoComponent\
\9\9then\
\9\9\9workInProgress.type = resolveFunctionForHotReloading(current.type)\
\9\9elseif workInProgress.tag == ClassComponent then\
\9\9\9workInProgress.type = resolveClassForHotReloading(current.type)\
\9\9elseif workInProgress.tag == ForwardRef then\
\9\9\9workInProgress.type = resolveForwardRefForHotReloading(current.type)\
\9\9end\
\9end\
\
\9return workInProgress\
end\
\
-- Used to reuse a Fiber for a second pass.\
local function resetWorkInProgress(workInProgress: Fiber, renderLanes: Lanes)\
\9-- This resets the Fiber to what createFiber or createWorkInProgress would\
\9-- have set the values to before during the first pass. Ideally this wouldn't\
\9-- be necessary but unfortunately many code paths reads from the workInProgress\
\9-- when they should be reading from current and writing to workInProgress.\
\
\9-- We assume pendingProps, index, key, ref, return are still untouched to\
\9-- avoid doing another reconciliation.\
\
\9-- Reset the effect tag but keep any Placement tags, since that's something\
\9-- that child fiber is setting, not the reconciliation.\
\9workInProgress.flags =\
\9\9bit32.band(workInProgress.flags, bit32.bor(StaticMask, Placement))\
\
\9-- The effects are no longer valid\
\
\9local current = workInProgress.alternate\
\9if current == nil then\
\9\9-- Reset to createFiber's initial values.\
\9\9workInProgress.childLanes = NoLanes\
\9\9workInProgress.lanes = renderLanes\
\
\9\9workInProgress.child = nil\
\9\9workInProgress.subtreeFlags = NoFlags\
\9\9workInProgress.memoizedProps = nil\
\9\9workInProgress.memoizedState = nil\
\9\9workInProgress.updateQueue = nil\
\
\9\9workInProgress.dependencies = nil\
\
\9\9workInProgress.stateNode = nil\
\
\9\9if enableProfilerTimer then\
\9\9\9-- Note: We don't reset the actualTime counts. It's useful to accumulate\
\9\9\9-- actual time across multiple render passes.\
\9\9\9workInProgress.selfBaseDuration = 0\
\9\9\9workInProgress.treeBaseDuration = 0\
\9\9end\
\9else\
\9\9-- Reset to the cloned values that createWorkInProgress would've.\
\9\9workInProgress.childLanes = current.childLanes\
\9\9workInProgress.lanes = current.lanes\
\
\9\9workInProgress.child = current.child\
\9\9workInProgress.subtreeFlags = current.subtreeFlags\
\9\9workInProgress.deletions = nil\
\9\9workInProgress.memoizedProps = current.memoizedProps\
\9\9workInProgress.memoizedState = current.memoizedState\
\9\9workInProgress.updateQueue = current.updateQueue\
\9\9-- Needed because Blocks store data on type.\
\9\9workInProgress.type = current.type\
\
\9\9-- Clone the dependencies object. This is mutated during the render phase, so\
\9\9-- it cannot be shared with the current fiber.\
\9\9local currentDependencies = current.dependencies\
\9\9if currentDependencies == nil then\
\9\9\9workInProgress.dependencies = nil\
\9\9else\
\9\9\9workInProgress.dependencies = {\
\9\9\9\9lanes = currentDependencies.lanes,\
\9\9\9\9firstContext = currentDependencies.firstContext,\
\9\9\9}\
\9\9end\
\
\9\9if enableProfilerTimer then\
\9\9\9-- Note: We don't reset the actualTime counts. It's useful to accumulate\
\9\9\9-- actual time across multiple render passes.\
\9\9\9workInProgress.selfBaseDuration = current.selfBaseDuration\
\9\9\9workInProgress.treeBaseDuration = current.treeBaseDuration\
\9\9end\
\9end\
\
\9return workInProgress\
end\
\
local function createHostRootFiber(tag: RootTag): Fiber\
\9local mode\
\9if tag == ConcurrentRoot then\
\9\9mode = bit32.bor(ConcurrentMode, BlockingMode, StrictMode)\
\9elseif tag == BlockingRoot then\
\9\9mode = bit32.bor(BlockingMode, StrictMode)\
\9else\
\9\9mode = NoMode\
\9end\
\
\9-- ROBLOX deviation: We use a function for isDevtoolsPresent to handle the hook being changed at runtime\
\9if enableProfilerTimer and isDevToolsPresent() then\
\9\9-- Always collect profile timings when DevTools are present.\
\9\9-- This enables DevTools to start capturing timing at any point–\
\9\9-- Without some nodes in the tree having empty base times.\
\9\9mode = bit32.bor(mode, ProfileMode)\
\9end\
\
\9return createFiber(HostRoot, nil, nil, mode)\
end\
\
local function createFiberFromTypeAndProps(\
\9type_: any, -- React$ElementType\
\9key: string?,\
\9pendingProps: any,\
\9owner: nil | Fiber,\
\9mode: TypeOfMode,\
\9lanes: Lanes\
): Fiber\
\9local fiberTag = IndeterminateComponent\
\9-- The resolved type is set if we know what the final type will be. I.e. it's not lazy.\
\9-- deviation: FIXME: Account for deviated class v. function component type logic\
\9local resolvedType = type_\
\9local typeOfType_ = type(type_)\
\9-- deviation: since our class components aren't functions, we have to look\
\9-- for them more explicitly (inlines logic from `shouldConstruct`)\
\9if typeOfType_ == \"function\" then\
\9\9if __DEV__ then\
\9\9\9resolvedType = resolveFunctionForHotReloading(resolvedType)\
\9\9end\
\9elseif typeOfType_ == \"table\" and not not type_.isReactComponent then\
\9\9fiberTag = ClassComponent\
\9\9if __DEV__ then\
\9\9\9resolvedType = resolveClassForHotReloading(resolvedType)\
\9\9end\
\9elseif typeOfType_ == \"string\" then\
\9\9fiberTag = HostComponent\
\9else\
\9\9if type_ == REACT_FRAGMENT_TYPE then\
\9\9\9return createFiberFromFragment(pendingProps.children, mode, lanes, key)\
\9\9elseif type_ == REACT_DEBUG_TRACING_MODE_TYPE then\
\9\9\9fiberTag = Mode\
\9\9\9mode = bit32.bor(mode, DebugTracingMode)\
\9\9elseif type_ == REACT_STRICT_MODE_TYPE then\
\9\9\9fiberTag = Mode\
\9\9\9mode = bit32.bor(mode, StrictMode)\
\9\9elseif type_ == REACT_PROFILER_TYPE then\
\9\9\9return createFiberFromProfiler(pendingProps, mode, lanes, key)\
\9\9elseif type_ == REACT_SUSPENSE_TYPE then\
\9\9\9return createFiberFromSuspense(pendingProps, mode, lanes, key)\
\9\9\9-- elseif type_ == REACT_SUSPENSE_LIST_TYPE then\
\9\9\9-- \9return createFiberFromSuspenseList(pendingProps, mode, lanes, key)\
\9\9elseif type_ == REACT_OFFSCREEN_TYPE then\
\9\9\9return createFiberFromOffscreen(pendingProps, mode, lanes, key)\
\9\9elseif type_ == REACT_LEGACY_HIDDEN_TYPE then\
\9\9\9return createFiberFromLegacyHidden(pendingProps, mode, lanes, key)\
\9\9\9-- elseif type_ == REACT_SCOPE_TYPE then\
\9\9\9-- \9if enableScopeAPI then\
\9\9\9-- \9\9return createFiberFromScope(type_, pendingProps, mode, lanes, key)\
\9\9\9-- \9end\
\9\9else\
\9\9\9local shouldBreak = false\
\9\9\9local type_typeof\
\9\9\9if typeOfType_ == \"table\" then\
\9\9\9\9type_typeof = type_[\"$$typeof\"]\
\9\9\9\9if type_typeof == REACT_PROVIDER_TYPE then\
\9\9\9\9\9fiberTag = ContextProvider\
\9\9\9\9\9shouldBreak = true\
\9\9\9\9elseif type_typeof == REACT_CONTEXT_TYPE then\
\9\9\9\9\9-- This is a consumer\
\9\9\9\9\9fiberTag = ContextConsumer\
\9\9\9\9\9shouldBreak = true\
\9\9\9\9elseif type_typeof == REACT_FORWARD_REF_TYPE then\
\9\9\9\9\9fiberTag = ForwardRef\
\9\9\9\9\9if __DEV__ then\
\9\9\9\9\9\9resolvedType = resolveForwardRefForHotReloading(resolvedType)\
\9\9\9\9\9end\
\9\9\9\9\9shouldBreak = true\
\9\9\9\9elseif type_typeof == REACT_MEMO_TYPE then\
\9\9\9\9\9fiberTag = MemoComponent\
\9\9\9\9\9shouldBreak = true\
\9\9\9\9elseif type_typeof == REACT_LAZY_TYPE then\
\9\9\9\9\9fiberTag = LazyComponent\
\9\9\9\9\9resolvedType = nil\
\9\9\9\9\9shouldBreak = true\
\9\9\9\9\9-- elseif type_typeof == REACT_FUNDAMENTAL_TYPE then\
\9\9\9\9\9-- \9if enableFundamentalAPI then\
\9\9\9\9\9-- \9\9return createFiberFromFundamental(\
\9\9\9\9\9-- \9\9\9type_,\
\9\9\9\9\9-- \9\9\9pendingProps,\
\9\9\9\9\9-- \9\9\9mode,\
\9\9\9\9\9-- \9\9\9lanes,\
\9\9\9\9\9-- \9\9\9key\
\9\9\9\9\9-- \9\9)\
\9\9\9\9\9-- \9end\
\9\9\9\9end\
\9\9\9end\
\9\9\9if not shouldBreak then\
\9\9\9\9local info = \"\"\
\9\9\9\9if __DEV__ then\
\9\9\9\9\9if\
\9\9\9\9\9\9type_ == nil\
\9\9\9\9\9\9or (typeOfType_ == \"table\" and #Object.keys(type_) == 0)\
\9\9\9\9\9then\
\9\9\9\9\9\9info ..= \" You likely forgot to export your component from the file \" .. \"it's defined in, or you might have mixed up default and \" .. \"named imports.\"\
\9\9\9\9\9elseif type_ ~= nil and typeOfType_ == \"table\" then\
\9\9\9\9\9\9-- ROBLOX deviation: print the table/string in readable form to give a clue, if no other info was gathered\
\9\9\9\9\9\9info ..= \"\\n\" .. inspect(type_)\
\9\9\9\9\9end\
\9\9\9\9\9local ownerName\
\9\9\9\9\9if owner then\
\9\9\9\9\9\9ownerName = getComponentName(owner.type)\
\9\9\9\9\9end\
\9\9\9\9\9if ownerName ~= nil and ownerName ~= \"\" then\
\9\9\9\9\9\9info ..= \"\\n\\nCheck the render method of `\" .. ownerName .. \"`.\"\
\9\9\9\9\9elseif owner then\
\9\9\9\9\9\9-- ROBLOX deviation: print the raw table in readable\
\9\9\9\9\9\9-- form to give a clue, if no other info was gathered\
\9\9\9\9\9\9info ..= \"\\n\" .. inspect(owner)\
\9\9\9\9\9end\
\9\9\9\9end\
\
\9\9\9\9-- ROBLOX deviation: make output logic consistent across ReactFiber, ElementValidator, Memo, Context, and Lazy\
\9\9\9\9local typeString\
\9\9\9\9if type_ == nil then\
\9\9\9\9\9typeString = \"nil\"\
\9\9\9\9elseif Array.isArray(type_) then\
\9\9\9\9\9typeString = \"array\"\
\9\9\9\9elseif typeOfType_ == \"table\" and type_typeof == REACT_ELEMENT_TYPE then\
\9\9\9\9\9typeString =\
\9\9\9\9\9\9string.format(\"<%s />\", getComponentName(type_.type) or \"Unknown\")\
\9\9\9\9\9info =\
\9\9\9\9\9\9\" Did you accidentally export a JSX literal or Element instead of a component?\"\
\9\9\9\9else\
\9\9\9\9\9typeString = typeOfType_\
\9\9\9\9end\
\
\9\9\9\9invariant(\
\9\9\9\9\9false,\
\9\9\9\9\9\"Element type is invalid: expected a string (for built-in \"\
\9\9\9\9\9\9.. \"components) or a class/function (for composite components) \"\
\9\9\9\9\9\9.. \"but got: %s.%s\",\
\9\9\9\9\9typeString,\
\9\9\9\9\9info\
\9\9\9\9)\
\9\9\9end\
\9\9end\
\9end\
\
\9-- ROBLOX deviation START: we pass in all needed values so the table creation+field assignment is a one-shot\
\9local fiber =\
\9\9createFiber(fiberTag, pendingProps, key, mode, type_, resolvedType, nil, lanes)\
\
\9-- fiber.elementType = type_\
\9-- fiber.type = resolvedType\
\9-- fiber.lanes = lanes\
\9-- ROBLOX deviation END\
\
\9if __DEV__ then\
\9\9fiber._debugOwner = owner\
\9end\
\
\9return fiber\
end\
\
local function createFiberFromElement(\
\9element: ReactElement,\
\9mode: TypeOfMode,\
\9lanes: Lanes\
): Fiber\
\9local owner = nil\
\9if __DEV__ then\
\9\9owner = element._owner\
\9end\
\9local type = element.type\
\9local key = element.key\
\9local pendingProps = element.props\
\9local fiber = createFiberFromTypeAndProps(\
\9\9type,\
\9\9-- ROBLOX FIXME: according to upstream types, key can only be string?, but RoactStableKey deviation also says number\
\9\9key :: string,\
\9\9pendingProps,\
\9\9owner,\
\9\9mode,\
\9\9lanes\
\9)\
\9if __DEV__ then\
\9\9fiber._debugSource = element._source\
\9\9fiber._debugOwner = element._owner\
\9end\
\9return fiber\
end\
