\9\9\9\9local nextPrimaryChildren = nextProps.children\
\9\9\9\9local fallbackChildFragment = updateSuspenseFallbackChildren(\
\9\9\9\9\9current,\
\9\9\9\9\9workInProgress,\
\9\9\9\9\9nextPrimaryChildren,\
\9\9\9\9\9nextFallbackChildren,\
\9\9\9\9\9renderLanes\
\9\9\9\9)\
\9\9\9\9local primaryChildFragment: Fiber = workInProgress.child :: any\
\9\9\9\9local prevOffscreenState: OffscreenState | nil = (current.child :: any).memoizedState\
