\9\9\9end\
\9\9end\
\9end\
end\
\
function mountSuspensePrimaryChildren(workInProgress, primaryChildren, renderLanes)\
\9local mode = workInProgress.mode\
\9local primaryChildProps: OffscreenProps = {\
\9\9mode = \"visible\",\
\9\9children = primaryChildren,\
\9}\
\9local primaryChildFragment =\
\9\9createFiberFromOffscreen(primaryChildProps, mode, renderLanes, nil)\
\9primaryChildFragment.return_ = workInProgress\
\9workInProgress.child = primaryChildFragment\
\9return primaryChildFragment\
end\
\
function mountSuspenseFallbackChildren(\
\9workInProgress,\
\9primaryChildren,\
\9fallbackChildren,\
\9renderLanes\
)\
\9local mode = workInProgress.mode\
\9local progressedPrimaryFragment: Fiber | nil = workInProgress.child\
\
\9local primaryChildProps: OffscreenProps = {\
\9\9mode = \"hidden\",\
\9\9children = primaryChildren,\
\9}\
\
\9local primaryChildFragment\
\9local fallbackChildFragment\
\9if bit32.band(mode, BlockingMode) == NoMode and progressedPrimaryFragment ~= nil then\
\9\9-- In legacy mode, we commit the primary tree as if it successfully\
\9\9-- completed, even though it's in an inconsistent state.\
\9\9primaryChildFragment = progressedPrimaryFragment\
\9\9primaryChildFragment.childLanes = ReactFiberLane.NoLanes\
\9\9primaryChildFragment.pendingProps = primaryChildProps\
\
\9\9if enableProfilerTimer and bit32.band(workInProgress.mode, ProfileMode) ~= 0 then\
\9\9\9-- Reset the durations from the first pass so they aren't included in the\
\9\9\9-- final amounts. This seems counterintuitive, since we're intentionally\
\9\9\9-- not measuring part of the render phase, but this makes it match what we\
\9\9\9-- do in Concurrent Mode.\
\9\9\9primaryChildFragment.actualDuration = 0\
\9\9\9primaryChildFragment.actualStartTime = -1\
\9\9\9primaryChildFragment.selfBaseDuration = 0\
\9\9\9primaryChildFragment.treeBaseDuration = 0\
\9\9end\
\
\9\9fallbackChildFragment =\
\9\9\9createFiberFromFragment(fallbackChildren, mode, renderLanes, nil)\
\9else\
\9\9primaryChildFragment =\
\9\9\9createFiberFromOffscreen(primaryChildProps, mode, ReactFiberLane.NoLanes, nil)\
\9\9fallbackChildFragment =\
\9\9\9createFiberFromFragment(fallbackChildren, mode, renderLanes, nil)\
\9end\
\
\9primaryChildFragment.return_ = workInProgress\
\9fallbackChildFragment.return_ = workInProgress\
\9primaryChildFragment.sibling = fallbackChildFragment\
\9workInProgress.child = primaryChildFragment\
\9return fallbackChildFragment\
end\
\
local function createWorkInProgressOffscreenFiber(\
\9current: Fiber,\
\9offscreenProps: OffscreenProps\
)\
\9-- The props argument to `createWorkInProgress` is `any` typed, so we use this\
\9-- wrapper function to constrain it.\
\9return createWorkInProgress(current, offscreenProps)\
end\
\
function updateSuspensePrimaryChildren(\
\9current,\
\9workInProgress,\
\9primaryChildren,\
\9renderLanes\
)\
\9local currentPrimaryChildFragment: Fiber = current.child :: any\
\9local currentFallbackChildFragment: Fiber | nil = currentPrimaryChildFragment.sibling\
\
\9local primaryChildFragment =\
\9\9createWorkInProgressOffscreenFiber(currentPrimaryChildFragment, {\
\9\9\9mode = \"visible\",\
\9\9\9children = primaryChildren,\
\9\9})\
\9if bit32.band(workInProgress.mode, BlockingMode) == NoMode then\
\9\9primaryChildFragment.lanes = renderLanes\
\9end\
\9primaryChildFragment.return_ = workInProgress\
\9primaryChildFragment.sibling = nil\
\9if currentFallbackChildFragment ~= nil then\
\9\9-- Delete the fallback child fragment\
\9\9local deletions = workInProgress.deletions\
\9\9if deletions == nil then\
\9\9\9workInProgress.deletions = { currentFallbackChildFragment }\
\9\9\9-- TODO (effects) Rename this to better reflect its new usage (e.g. ChildDeletions)\
\9\9\9workInProgress.flags = bit32.bor(workInProgress.flags, Deletion)\
\9\9else\
\9\9\9table.insert(deletions, currentFallbackChildFragment)\
\9\9end\
\9end\
\
\9workInProgress.child = primaryChildFragment\
\9return primaryChildFragment\
end\
\
function updateSuspenseFallbackChildren(\
\9current,\
\9workInProgress,\
\9primaryChildren,\
\9fallbackChildren,\
\9renderLanes\
)\
\9local mode = workInProgress.mode\
\9local currentPrimaryChildFragment: Fiber = current.child :: any\
\9local currentFallbackChildFragment: Fiber | nil = currentPrimaryChildFragment.sibling\
\
\9local primaryChildProps: OffscreenProps = {\
\9\9mode = \"hidden\",\
\9\9children = primaryChildren,\
\9}\
\
\9local primaryChildFragment\
\9if\
\9\9-- In legacy mode, we commit the primary tree as if it successfully\
\9\9-- completed, even though it's in an inconsistent state.\
\9\9bit32.band(mode, BlockingMode) == NoMode\
\9\9-- Make sure we're on the second pass, i.e. the primary child fragment was\
\9\9-- already cloned. In legacy mode, the only case where this isn't true is\
\9\9-- when DevTools forces us to display a fallback; we skip the first render\
\9\9-- pass entirely and go straight to rendering the fallback. (In Concurrent\
\9\9-- Mode, SuspenseList can also trigger this scenario, but this is a legacy-\
\9\9-- only codepath.)\
\9\9and workInProgress.child ~= currentPrimaryChildFragment\
\9then\
\9\9local progressedPrimaryFragment: Fiber = workInProgress.child\
\9\9primaryChildFragment = progressedPrimaryFragment\
\9\9primaryChildFragment.childLanes = ReactFiberLane.NoLanes\
\9\9primaryChildFragment.pendingProps = primaryChildProps\
\
\9\9if enableProfilerTimer and bit32.band(workInProgress.mode, ProfileMode) ~= 0 then\
\9\9\9-- Reset the durations from the first pass so they aren't included in the\
\9\9\9-- final amounts. This seems counterintuitive, since we're intentionally\
\9\9\9-- not measuring part of the render phase, but this makes it match what we\
\9\9\9-- do in Concurrent Mode.\
\9\9\9primaryChildFragment.actualDuration = 0\
\9\9\9primaryChildFragment.actualStartTime = -1\
\9\9\9primaryChildFragment.selfBaseDuration =\
\9\9\9\9currentPrimaryChildFragment.selfBaseDuration\
\9\9\9primaryChildFragment.treeBaseDuration =\
\9\9\9\9currentPrimaryChildFragment.treeBaseDuration\
\9\9end\
\
\9\9-- The fallback fiber was added as a deletion effect during the first pass.\
\9\9-- However, since we're going to remain on the fallback, we no longer want\
\9\9-- to delete it.\
\9\9workInProgress.deletions = nil\
\9else\
\9\9primaryChildFragment = createWorkInProgressOffscreenFiber(\
\9\9\9currentPrimaryChildFragment,\
\9\9\9primaryChildProps\
\9\9)\
\
\9\9-- Since we're reusing a current tree, we need to reuse the flags, too.\
\9\9-- (We don't do this in legacy mode, because in legacy mode we don't re-use\
\9\9-- the current tree; see previous branch.)\
\9\9primaryChildFragment.subtreeFlags =\
\9\9\9bit32.band(currentPrimaryChildFragment.subtreeFlags, StaticMask)\
\9end\
\9local fallbackChildFragment\
\9if currentFallbackChildFragment ~= nil then\
\9\9fallbackChildFragment =\
\9\9\9createWorkInProgress(currentFallbackChildFragment, fallbackChildren)\
\9else\
\9\9fallbackChildFragment =\
\9\9\9createFiberFromFragment(fallbackChildren, mode, renderLanes, nil)\
\9\9-- Needs a placement effect because the parent (the Suspense boundary) already\
\9\9-- mounted but this is a new fiber.\
\9\9fallbackChildFragment.flags = bit32.bor(fallbackChildFragment.flags, Placement)\
\9end\
\
\9fallbackChildFragment.return_ = workInProgress\
\9primaryChildFragment.return_ = workInProgress\
\9primaryChildFragment.sibling = fallbackChildFragment\
\9workInProgress.child = primaryChildFragment\
\
\9return fallbackChildFragment\
end\
\
local function retrySuspenseComponentWithoutHydrating(\
\9current: Fiber,\
\9workInProgress: Fiber,\
\9renderLanes: Lanes\
)\
\9-- This will add the old fiber to the deletion list\
\9reconcileChildFibers(workInProgress, current.child, nil, renderLanes)\
\
\9-- We're now not suspended nor dehydrated.\
\9local nextProps = workInProgress.pendingProps\
\9local primaryChildren = nextProps.children\
\9local primaryChildFragment =\
\9\9mountSuspensePrimaryChildren(workInProgress, primaryChildren, renderLanes)\
\9-- Needs a placement effect because the parent (the Suspense boundary) already\
\9-- mounted but this is a new fiber.\
\9primaryChildFragment.flags = bit32.bor(primaryChildFragment.flags, Placement)\
\9workInProgress.memoizedState = nil\
\
\9return primaryChildFragment\
end\
\
function mountSuspenseFallbackAfterRetryWithoutHydrating(\
\9current,\
\9workInProgress,\
\9primaryChildren,\
\9fallbackChildren,\
\9renderLanes\
)\
\9local mode = workInProgress.mode\
\9local primaryChildFragment =\
\9\9createFiberFromOffscreen(primaryChildren, mode, ReactFiberLane.NoLanes, nil)\
\9local fallbackChildFragment =\
\9\9createFiberFromFragment(fallbackChildren, mode, renderLanes, nil)\
\9-- Needs a placement effect because the parent (the Suspense\
\9-- boundary) already mounted but this is a new fiber.\
\9fallbackChildFragment.flags = bit32.bor(fallbackChildFragment.flags, Placement)\
\
\9primaryChildFragment.return_ = workInProgress\
\9fallbackChildFragment.return_ = workInProgress\
\9primaryChildFragment.sibling = fallbackChildFragment\
\9workInProgress.child = primaryChildFragment\
\
\9if bit32.band(workInProgress.mode, BlockingMode) ~= NoMode then\
\9\9-- We will have dropped the effect list which contains the\
\9\9-- deletion. We need to reconcile to delete the current child.\
\9\9reconcileChildFibers(workInProgress, current.child, nil, renderLanes)\
\9end\
\
\9return fallbackChildFragment\
end\
\
function mountDehydratedSuspenseComponent(\
\9workInProgress: Fiber,\
\9suspenseInstance: SuspenseInstance,\
\9renderLanes: Lanes\
): nil | Fiber\
\9-- During the first pass, we'll bail out and not drill into the children.\
\9-- Instead, we'll leave the content in place and try to hydrate it later.\
\9if bit32.band(workInProgress.mode, BlockingMode) == NoMode then\
\9\9if __DEV__ then\
\9\9\9console.error(\
\9\9\9\9\"Cannot hydrate Suspense in legacy mode. Switch from\"\
\9\9\9\9\9.. \"ReactDOM.hydrate(element, container) to \"\
\9\9\9\9\9.. \"ReactDOM.createBlockingRoot(container, { hydrate: true })\"\
\9\9\9\9\9.. \".render(element) or remove the Suspense components\"\
\9\9\9\9\9.. \"the server rendered components.\"\
\9\9\9)\
\9\9end\
\9\9workInProgress.lanes = ReactFiberLane.laneToLanes(ReactFiberLane.SyncLane)\
\9elseif isSuspenseInstanceFallback(suspenseInstance) then\
\9\9-- This is a client-only boundary. Since we won't get any content from the server\
\9\9-- for this, we need to schedule that at a higher priority based on when it would\
\9\9-- have timed out. In theory we could render it in this pass but it would have the\
\9\9-- wrong priority associated with it and will prevent hydration of parent path.\
\9\9-- Instead, we'll leave work left on it to render it in a separate commit.\
\
\9\9-- TODO This time should be the time at which the server rendered response that is\
\9\9-- a parent to this boundary was displayed. However, since we currently don't have\
\9\9-- a protocol to transfer that time, we'll just estimate it by using the current\
\9\9-- time. This will mean that Suspense timeouts are slightly shifted to later than\
\9\9-- they should be.\
\9\9-- Schedule a normal pri update to render this content.\
\9\9if enableSchedulerTracing then\
\9\9\9markSpawnedWork(ReactFiberLane.DefaultHydrationLane)\
\9\9end\
\9\9workInProgress.lanes =\
\9\9\9ReactFiberLane.laneToLanes(ReactFiberLane.DefaultHydrationLane)\
\9else\
\9\9-- We'll continue hydrating the rest at offscreen priority since we'll already\
\9\9-- be showing the right content coming from the server, it is no rush.\
\9\9workInProgress.lanes = ReactFiberLane.laneToLanes(ReactFiberLane.OffscreenLane)\
\9\9if enableSchedulerTracing then\
\9\9\9markSpawnedWork(ReactFiberLane.OffscreenLane)\
\9\9end\
\9end\
\9return nil\
end\
\
function updateDehydratedSuspenseComponent(\
\9current: Fiber,\
\9workInProgress: Fiber,\
\9suspenseInstance: SuspenseInstance,\
\9suspenseState: SuspenseState,\
\9renderLanes: Lanes\
): nil | Fiber\
\9-- We should never be hydrating at this point because it is the first pass,\
\9-- but after we've already committed once.\
\9warnIfHydrating()\
\
\9if bit32.band(getExecutionContext(), RetryAfterError) ~= NoContext then\
\9\9return retrySuspenseComponentWithoutHydrating(\
\9\9\9current,\
\9\9\9workInProgress,\
\9\9\9renderLanes\
\9\9)\
\9end\
\
\9if bit32.band(workInProgress.mode, BlockingMode) == NoMode then\
\9\9return retrySuspenseComponentWithoutHydrating(\
\9\9\9current,\
\9\9\9workInProgress,\
\9\9\9renderLanes\
\9\9)\
\9end\
\
\9if isSuspenseInstanceFallback(suspenseInstance) then\
\9\9-- This boundary is in a permanent fallback state. In this case, we'll never\
\9\9-- get an update and we'll never be able to hydrate the final content. Let's just try the\
\9\9-- client side render instead.\
\9\9return retrySuspenseComponentWithoutHydrating(\
\9\9\9current,\
\9\9\9workInProgress,\
\9\9\9renderLanes\
\9\9)\
\9end\
\9-- We use lanes to indicate that a child might depend on context, so if\
\9-- any context has changed, we need to treat is as if the input might have changed.\
\9local hasContextChanged =\
\9\9ReactFiberLane.includesSomeLane(renderLanes, current.childLanes)\
\9if didReceiveUpdate or hasContextChanged then\
\9\9-- This boundary has changed since the first render. This means that we are now unable to\
\9\9-- hydrate it. We might still be able to hydrate it using a higher priority lane.\
\9\9local root = getWorkInProgressRoot()\
\9\9if root ~= nil then\
\9\9\9local attemptHydrationAtLane =\
\9\9\9\9ReactFiberLane.getBumpedLaneForHydration(root, renderLanes)\
\9\9\9if\
\9\9\9\9attemptHydrationAtLane ~= ReactFiberLane.NoLane\
\9\9\9\9and attemptHydrationAtLane ~= suspenseState.retryLane\
\9\9\9then\
\9\9\9\9-- Intentionally mutating since this render will get interrupted. This\
\9\9\9\9-- is one of the very rare times where we mutate the current tree\
\9\9\9\9-- during the render phase.\
\9\9\9\9suspenseState.retryLane = attemptHydrationAtLane\
\9\9\9\9-- TODO: Ideally this would inherit the event time of the current render\
\9\9\9\9local eventTime = ReactFiberLane.NoTimestamp\
\9\9\9\9scheduleUpdateOnFiber(current, attemptHydrationAtLane, eventTime)\
\9\9\9else\
\9\9\9\9-- We have already tried to ping at a higher priority than we're rendering with\
\9\9\9\9-- so if we got here, we must have failed to hydrate at those levels. We must\
\9\9\9\9-- now give up. Instead, we're going to delete the whole subtree and instead inject\
\9\9\9\9-- a new real Suspense boundary to take its place, which may render content\
\9\9\9\9-- or fallback. This might suspend for a while and if it does we might still have\
\9\9\9\9-- an opportunity to hydrate before this pass commits.\
\9\9\9end\
\9\9end\
\
\9\9-- If we have scheduled higher pri work above, this will probably just abort the render\
\9\9-- since we now have higher priority work, but in case it doesn't, we need to prepare to\
\9\9-- render something, if we time out. Even if that requires us to delete everything and\
\9\9-- skip hydration.\
\9\9-- Delay having to do this as long as the suspense timeout allows us.\
\9\9renderDidSuspendDelayIfPossible()\
\9\9return retrySuspenseComponentWithoutHydrating(\
\9\9\9current,\
\9\9\9workInProgress,\
\9\9\9renderLanes\
\9\9)\
\9elseif isSuspenseInstancePending(suspenseInstance) then\
\9\9-- This component is still pending more data from the server, so we can't hydrate its\
\9\9-- content. We treat it as if this component suspended itself. It might seem as if\
\9\9-- we could just try to render it client-side instead. However, this will perform a\
\9\9-- lot of unnecessary work and is unlikely to complete since it often will suspend\
\9\9-- on missing data anyway. Additionally, the server might be able to render more\
\9\9-- than we can on the client yet. In that case we'd end up with more fallback states\
\9\9-- on the client than if we just leave it alone. If the server times out or errors\
\9\9-- these should update this boundary to the permanent Fallback state instead.\
\9\9-- Mark it as having captured (i.e. suspended).\
\9\9workInProgress.flags = bit32.bor(workInProgress.flags, DidCapture)\
\9\9-- Leave the child in place. I.e. the dehydrated fragment.\
\9\9workInProgress.child = current.child\
\
\9\9-- Register a callback to retry this boundary once the server has sent the result.\
\9\9-- ROBLOX deviation: wrapper function in place of bind\
\9\9local retry = function()\
\9\9\9return retryDehydratedSuspenseBoundary(current)\
\9\9end\
\
\9\9if enableSchedulerTracing then\
\9\9\9if Schedule_tracing_wrap == nil then\
\9\9\9\9Schedule_tracing_wrap = require(Packages.Scheduler).tracing.unstable_wrap\
\9\9\9end\
\9\9\9retry = Schedule_tracing_wrap(retry)\
\9\9end\
\
\9\9registerSuspenseInstanceRetry(suspenseInstance, retry)\
\9\9return nil\
\9else\
\9\9-- This is the first attempt.\
\9\9reenterHydrationStateFromDehydratedSuspenseInstance(\
\9\9\9workInProgress,\
\9\9\9suspenseInstance\
\9\9)\
\9\9local nextProps = workInProgress.pendingProps\
\9\9local primaryChildren = nextProps.children\
\9\9local primaryChildFragment =\
\9\9\9mountSuspensePrimaryChildren(workInProgress, primaryChildren, renderLanes)\
\9\9-- Mark the children as hydrating. This is a fast path to know whether this\
\9\9-- tree is part of a hydrating tree. This is used to determine if a child\
\9\9-- node has fully mounted yet, and for scheduling event replaying.\
\9\9-- Conceptually this is similar to Placement in that a new subtree is\
\9\9-- inserted into the React tree here. It just happens to not need DOM\
\9\9-- mutations because it already exists.\
\9\9primaryChildFragment.flags = bit32.bor(primaryChildFragment.flags, Hydrating)\
\9\9return primaryChildFragment\
\9end\
end\
