\9\9\9then\
\9\9\9\9if instance.props ~= finishedWork.memoizedProps then\
\9\9\9\9\9console.error(\
\9\9\9\9\9\9\"Expected %s props to match memoized props before \"\
\9\9\9\9\9\9\9.. \"processing the update queue. \"\
\9\9\9\9\9\9\9.. \"This might either be because of a bug in React, or because \"\
\9\9\9\9\9\9\9.. \"a component reassigns its own `this.props`. \"\
\9\9\9\9\9\9\9.. \"Please file an issue.\",\
\9\9\9\9\9\9getComponentName(finishedWork.type) or \"instance\"\
\9\9\9\9\9)\
\9\9\9\9end\
\9\9\9\9if instance.state ~= finishedWork.memoizedState then\
\9\9\9\9\9console.error(\
\9\9\9\9\9\9\"Expected %s state to match memoized state before \"\
\9\9\9\9\9\9\9.. \"processing the update queue. \"\
\9\9\9\9\9\9\9.. \"This might either be because of a bug in React, or because \"\
\9\9\9\9\9\9\9.. \"a component reassigns its own `this.state`. \"\
\9\9\9\9\9\9\9.. \"Please file an issue.\",\
\9\9\9\9\9\9getComponentName(finishedWork.type) or \"instance\"\
\9\9\9\9\9)\
\9\9\9\9end\
\9\9\9end\
\9\9end\
\9\9-- We could update instance props and state here,\
\9\9-- but instead we rely on them being set during last render.\
\9\9-- TODO: revisit this when we implement resuming.\
\9\9commitUpdateQueue(finishedWork, updateQueue, instance)\
\9end\
end\
\
function commitLayoutEffectsForHostRoot(finishedWork: Fiber)\
\9-- TODO: I think this is now always non-null by the time it reaches the\
\9-- commit phase. Consider removing the type check.\
\9local updateQueue: UpdateQueue<any> | nil = finishedWork.updateQueue\
\9if updateQueue ~= nil then\
\9\9local instance = nil\
\9\9if finishedWork.child ~= nil then\
\9\9\9-- ROBLOX TODO: localize child, workaround Luau type refinement shortcomings\
\9\9\9local child = finishedWork.child\
\9\9\9if child.tag == HostComponent then\
\9\9\9\9instance = getPublicInstance(child.stateNode)\
\9\9\9elseif child.tag == ClassComponent then\
\9\9\9\9instance = child.stateNode\
\9\9\9end\
\9\9end\
\9\9commitUpdateQueue(finishedWork, updateQueue, instance)\
\9end\
end\
\
function commitLayoutEffectsForHostComponent(finishedWork: Fiber)\
\9local instance: Instance = finishedWork.stateNode\
\9local current = finishedWork.alternate\
\
\9-- Renderers may schedule work to be done after host components are mounted\
\9-- (eg DOM renderer may schedule auto-focus for inputs and form controls).\
\9-- These effects should only be committed when components are first mounted,\
\9-- aka when there is no current/alternate.\
\9if current == nil and bit32.band(finishedWork.flags, Update) ~= 0 then\
\9\9local type = finishedWork.type\
\9\9local props = finishedWork.memoizedProps\
\9\9commitMount(instance, type, props, finishedWork)\
\9end\
end\
\
local function hideOrUnhideAllChildren(finishedWork, isHidden)\
\9if supportsMutation then\
\9\9-- We only have the top Fiber that was inserted but we need to recurse down its\
\9\9-- children to find all the terminal nodes.\
\9\9local node: Fiber = finishedWork\
\9\9while true do\
\9\9\9if node.tag == HostComponent then\
\9\9\9\9local instance = node.stateNode\
\9\9\9\9if isHidden then\
\9\9\9\9\9hideInstance(instance)\
\9\9\9\9else\
\9\9\9\9\9unhideInstance(node.stateNode, node.memoizedProps)\
\9\9\9\9end\
\9\9\9elseif node.tag == HostText then\
\9\9\9\9local instance = node.stateNode\
\9\9\9\9if isHidden then\
\9\9\9\9\9hideTextInstance(instance)\
\9\9\9\9else\
\9\9\9\9\9unhideTextInstance(instance, node.memoizedProps)\
\9\9\9\9end\
\9\9\9elseif\
\9\9\9\9(node.tag == OffscreenComponent or node.tag == LegacyHiddenComponent)\
\9\9\9\9and (node.memoizedState :: OffscreenState) ~= nil\
\9\9\9\9and node ~= finishedWork\
\9\9\9then\
\9\9\9-- Found a nested Offscreen component that is hidden. Don't search\
\9\9\9-- any deeper. This tree should remain hidden.\
\9\9\9elseif node.child ~= nil then\
\9\9\9\9-- ROBLOX FIXME: type casts to silence analyze, Luau doesn't understand nil check\
\9\9\9\9(node.child :: Fiber).return_ = node\
\9\9\9\9node = node.child :: Fiber\
\9\9\9\9continue\
\9\9\9end\
\9\9\9if node == finishedWork then\
\9\9\9\9return\
\9\9\9end\
\9\9\9while node.sibling == nil do\
\9\9\9\9if node.return_ == nil or node.return_ == finishedWork then\
\9\9\9\9\9return\
\9\9\9\9end\
\9\9\9\9node = node.return_ :: Fiber -- ROBLOX TODO: Luau narrowing doesn't understand this loop until nil pattern\
\9\9\9end\
\9\9\9-- ROBLOX FIXME: cast to any to silence analyze\
\9\9\9(node.sibling :: Fiber).return_ = node.return_\
\9\9\9-- ROBLOX FIXME: recast to silence analyze while Luau doesn't understand nil check\
\9\9\9node = node.sibling :: Fiber\
\9\9end\
\9end\
end\
\
function commitAttachRef(finishedWork: Fiber)\
\9local ref = finishedWork.ref\
\9if ref ~= nil then\
\9\9local instance = finishedWork.stateNode\
\9\9local instanceToUse\
\9\9if finishedWork.tag == HostComponent then\
\9\9\9instanceToUse = getPublicInstance(instance)\
\9\9else\
\9\9\9instanceToUse = instance\
\9\9end\
\9\9-- Moved outside to ensure DCE works with this flag\
\9\9-- ROBLOX performance: avoid cmp on always-false value\
\9\9-- if enableScopeAPI and finishedWork.tag == ScopeComponent then\
\9\9--   instanceToUse = instance\
\9\9-- end\
\9\9if typeof(ref) == \"function\" then\
\9\9\9ref(instanceToUse)\
\9\9else\
\9\9\9if __DEV__ then\
\9\9\9\9-- ROBLOX FIXME: We won't be able to recognize a ref object by checking\
\9\9\9\9-- for the existence of the `current` key, since it won't be initialized\
\9\9\9\9-- at this point. We might consider using a symbol to uniquely identify\
\9\9\9\9-- ref objects, or relying more heavily on Luau types\
\9\9\9\9-- if not ref.current then\
\9\9\9\9if typeof(ref) ~= \"table\" then\
\9\9\9\9\9console.error(\
\9\9\9\9\9\9\"Unexpected ref object provided for %s. \"\
\9\9\9\9\9\9\9.. \"Use either a ref-setter function or React.createRef().\",\
\9\9\9\9\9\9getComponentName(finishedWork.type) or \"instance\"\
\9\9\9\9\9)\
\9\9\9\9\9return\
\9\9\9\9end\
\9\9\9end\
\
\9\9\9ref.current = instanceToUse\
\9\9end\
\9end\
end\
\
function commitDetachRef(current: Fiber)\
\9local currentRef = current.ref\
\9if currentRef ~= nil then\
\9\9if typeof(currentRef) == \"function\" then\
\9\9\9currentRef(nil)\
\9\9else\
\9\9\9currentRef.current = nil\
\9\9end\
\9end\
end\
\
-- User-originating errors (lifecycles and refs) should not interrupt\
-- deletion, so don't local them throw. Host-originating errors should\
-- interrupt deletion, so it's okay\
function commitUnmount(\
\9finishedRoot: FiberRoot,\
\9current: Fiber,\
\9nearestMountedAncestor: Fiber,\
\9renderPriorityLevel: ReactPriorityLevel\
): ()\
\9onCommitUnmount(current)\
\
\9if\
\9\9current.tag == FunctionComponent\
\9\9or current.tag == ForwardRef\
\9\9or current.tag == MemoComponent\
\9\9or current.tag == SimpleMemoComponent\
\9\9or current.tag == Block\
\9then\
\9\9local updateQueue: FunctionComponentUpdateQueue | nil = current.updateQueue\
\9\9if updateQueue ~= nil then\
\9\9\9local lastEffect = (updateQueue :: FunctionComponentUpdateQueue).lastEffect\
\9\9\9if lastEffect ~= nil then\
\9\9\9\9local firstEffect = lastEffect.next\
\
\9\9\9\9local effect = firstEffect\
\9\9\9\9repeat\
\9\9\9\9\9if effect.destroy ~= nil then\
\9\9\9\9\9\9if bit32.band(effect.tag, HookLayout) ~= NoHookEffect then\
\9\9\9\9\9\9\9if\
\9\9\9\9\9\9\9\9enableProfilerTimer\
\9\9\9\9\9\9\9\9and enableProfilerCommitHooks\
\9\9\9\9\9\9\9\9and bit32.band(current.mode, ProfileMode) ~= 0\
\9\9\9\9\9\9\9then\
\9\9\9\9\9\9\9\9startLayoutEffectTimer()\
\9\9\9\9\9\9\9\9safelyCallDestroy(\
\9\9\9\9\9\9\9\9\9current,\
\9\9\9\9\9\9\9\9\9nearestMountedAncestor,\
\9\9\9\9\9\9\9\9\9effect.destroy\
\9\9\9\9\9\9\9\9)\
\9\9\9\9\9\9\9\9recordLayoutEffectDuration(current)\
\9\9\9\9\9\9\9else\
\9\9\9\9\9\9\9\9safelyCallDestroy(\
\9\9\9\9\9\9\9\9\9current,\
\9\9\9\9\9\9\9\9\9nearestMountedAncestor,\
\9\9\9\9\9\9\9\9\9effect.destroy\
\9\9\9\9\9\9\9\9)\
\9\9\9\9\9\9\9end\
\9\9\9\9\9\9end\
\9\9\9\9\9end\
\9\9\9\9\9effect = effect.next\
\9\9\9\9until effect == firstEffect\
\9\9\9end\
\9\9end\
\9\9return\
\9elseif current.tag == ClassComponent then\
\9\9safelyDetachRef(current, nearestMountedAncestor)\
\9\9local instance = current.stateNode\
\9\9if typeof(instance.componentWillUnmount) == \"function\" then\
\9\9\9safelyCallComponentWillUnmount(current, instance, nearestMountedAncestor)\
\9\9end\
\9\9return\
\9elseif current.tag == HostComponent then\
\9\9safelyDetachRef(current, nearestMountedAncestor)\
\9\9return\
\9elseif current.tag == HostPortal then\
\9\9-- TODO: this is recursive.\
\9\9-- We are also not using this parent because\
\9\9-- the portal will get pushed immediately.\
\9\9if supportsMutation then\
\9\9\9unmountHostComponents(\
\9\9\9\9finishedRoot,\
\9\9\9\9current,\
\9\9\9\9nearestMountedAncestor,\
\9\9\9\9renderPriorityLevel\
\9\9\9)\
\9\9elseif supportsPersistence then\
\9\9\9unimplemented(\"emptyPortalContainer\")\
\9\9\9-- emptyPortalContainer(current)\
\9\9end\
\9\9return\
\9\9-- elseif current.tag == FundamentalComponent then\
\9\9--   unimplemented(\"commitUnmount - FundamentalComponent\")\
\9\9-- if enableFundamentalAPI then\
\9\9--   local fundamentalInstance = current.stateNode\
\9\9--   if fundamentalInstance ~= nil then\
\9\9--     unmountFundamentalComponent(fundamentalInstance)\
\9\9--     current.stateNode = nil\
\9\9--   end\
\9\9-- end\
\9\9-- return\
\9\9-- elseif current.tag == DehydratedFragment then\
\9\9--   unimplemented(\"commitUnmount - DehydratedFragment\")\
\9\9-- if enableSuspenseCallback then\
\9\9--   local hydrationCallbacks = finishedRoot.hydrationCallbacks\
\9\9--   if hydrationCallbacks ~= nil then\
\9\9--     local onDeleted = hydrationCallbacks.onDeleted\
\9\9--     if onDeleted then\
\9\9--       onDeleted((current.stateNode: SuspenseInstance))\
\9\9--     end\
\9\9--   end\
\9\9-- end\
\9\9-- return\
\9\9-- elseif current.tag == ScopeComponent then\
\9\9--   if enableScopeAPI then\
\9\9--     safelyDetachRef(current, nearestMountedAncestor)\
\9\9--   end\
\9\9--   return\
\9end\
end\
\
function commitNestedUnmounts(\
\9finishedRoot: FiberRoot,\
\9root: Fiber,\
\9nearestMountedAncestor: Fiber,\
\9renderPriorityLevel: ReactPriorityLevel\
)\
\9-- While we're inside a removed host node we don't want to call\
\9-- removeChild on the inner nodes because they're removed by the top\
\9-- call anyway. We also want to call componentWillUnmount on all\
\9-- composites before this host node is removed from the tree. Therefore\
\9-- we do an inner loop while we're still inside the host node.\
\9local node: Fiber = root\
\9while true do\
\9\9commitUnmount(finishedRoot, node, nearestMountedAncestor, renderPriorityLevel)\
\9\9-- Visit children because they may contain more composite or host nodes.\
\9\9-- Skip portals because commitUnmount() currently visits them recursively.\
\9\9if\
\9\9\9node.child ~= nil\
\9\9\9-- If we use mutation we drill down into portals using commitUnmount above.\
\9\9\9-- If we don't use mutation we drill down into portals here instead.\
\9\9\9and (not supportsMutation or node.tag ~= HostPortal)\
\9\9then\
\9\9\9(node.child :: Fiber).return_ = node\
\9\9\9node = node.child :: Fiber\
\9\9\9continue\
\9\9end\
\9\9if node == root then\
\9\9\9return\
\9\9end\
\9\9while node.sibling == nil do\
\9\9\9if node.return_ == nil or node.return_ == root then\
\9\9\9\9return\
\9\9\9end\
\9\9\9node = node.return_ :: Fiber -- ROBLOX TODO: Luau narrowing doesn't understand this loop until nil pattern\
\9\9end\
\9\9(node.sibling :: Fiber).return_ = node.return_\
\9\9node = node.sibling :: Fiber\
\9end\
end\
\
local function detachFiberMutation(fiber: Fiber)\
\9-- Cut off the return pointer to disconnect it from the tree.\
\9-- This enables us to detect and warn against state updates on an unmounted component.\
\9-- It also prevents events from bubbling from within disconnected components.\
\9--\
\9-- Ideally, we should also clear the child pointer of the parent alternate to local this\
\9-- get GC:ed but we don't know which for sure which parent is the current\
\9-- one so we'll settle for GC:ing the subtree of this child.\
\9-- This child itself will be GC:ed when the parent updates the next time.\
\9--\
\9-- Note that we can't clear child or sibling pointers yet.\
\9-- They're needed for passive effects and for findDOMNode.\
\9-- We defer those fields, and all other cleanup, to the passive phase (see detachFiberAfterEffects).\
\9local alternate = fiber.alternate\
\9if alternate ~= nil then\
\9\9alternate.return_ = nil\
\9\9if not enableNewTreeCleanupPath then\
\9\9\9fiber.alternate = nil\
\9\9end\
\9end\
\9fiber.return_ = nil\
end\
\
