--   if !supportsPersistence)\
--     return\
--   end\
\
--   local portal: {\
--     containerInfo: Container,\
--     pendingChildren: ChildSet,\
--     ...\
--   } = current.stateNode\
--   local {containerInfo} = portal\
--   local emptyChildSet = createContainerChildSet(containerInfo)\
--   replaceContainerChildren(containerInfo, emptyChildSet)\
-- end\
\
-- function commitContainer(finishedWork: Fiber)\
--   if !supportsPersistence)\
--     return\
--   end\
\
--   switch (finishedWork.tag)\
--     case ClassComponent:\
--     case HostComponent:\
--     case HostText:\
--     case FundamentalComponent: {\
--       return\
--     end\
--     case HostRoot:\
--     case HostPortal: {\
--       local portalOrRoot: {\
--         containerInfo: Container,\
--         pendingChildren: ChildSet,\
--         ...\
--       } = finishedWork.stateNode\
--       local {containerInfo, pendingChildren} = portalOrRoot\
--       replaceContainerChildren(containerInfo, pendingChildren)\
--       return\
--     end\
--   end\
--   invariant(\
--     false,\
--     'This unit of work tag should not have side-effects. This error is ' +\
--       'likely caused by a bug in React. Please file an issue.',\
--   )\
-- end\
\
local function getHostParentFiber(fiber: Fiber): Fiber\
\9local parent = fiber.return_\
\9while parent ~= nil do\
\9\9if isHostParent(parent) then\
\9\9\9return parent\
\9\9end\
\9\9parent = parent.return_\
\9end\
\9-- ROBLOX deviation START: use React 18 approach, which Luau understands better than invariant\
\9error(\
\9\9Error.new(\
\9\9\9\"Expected to find a host parent. This error is likely caused by a bug \"\
\9\9\9\9.. \"in React. Please file an issue.\"\
\9\9)\
\9)\
\9-- ROBLOX deviation END\
end\
\
function isHostParent(fiber: Fiber): boolean\
\9return fiber.tag == HostComponent or fiber.tag == HostRoot or fiber.tag == HostPortal\
end\
\
function getHostSibling(fiber: Fiber): Instance?\
\9-- We're going to search forward into the tree until we find a sibling host\
\9-- node. Unfortunately, if multiple insertions are done in a row we have to\
\9-- search past them. This leads to exponential search for the next sibling.\
\9-- TODO: Find a more efficient way to do this.\
\9local node: Fiber = fiber\
\9while true do\
\9\9-- ROBLOX deviation: we can't `continue` with labels in luau, so some variable\
\9\9-- juggling is used instead\
\9\9local continueOuter = false\
\9\9-- If we didn't find anything, let's try the next sibling.\
\9\9while node.sibling == nil do\
\9\9\9if node.return_ == nil or isHostParent(node.return_) then\
\9\9\9\9-- If we pop out of the root or hit the parent the fiber we are the\
\9\9\9\9-- last sibling.\
\9\9\9\9return nil\
\9\9\9end\
\9\9\9node = node.return_ :: Fiber -- ROBLOX TODO: Luau narrowing doesn't understand this loop until nil pattern\
\9\9end\
\9\9(node.sibling :: Fiber).return_ = node.return_ :: Fiber\
\9\9node = node.sibling :: Fiber\
\9\9while\
\9\9\9node.tag ~= HostComponent\
\9\9\9and node.tag ~= HostText\
\9\9\9and node.tag ~= DehydratedFragment\
\9\9do\
\9\9\9-- If it is not host node and, we might have a host node inside it.\
\9\9\9-- Try to search down until we find one.\
\9\9\9if bit32.band(node.flags, Placement) ~= 0 then\
\9\9\9\9-- If we don't have a child, try the siblings instead.\
\9\9\9\9continueOuter = true\
\9\9\9\9break\
\9\9\9end\
\9\9\9-- If we don't have a child, try the siblings instead.\
\9\9\9-- We also skip portals because they are not part of this host tree.\
\9\9\9if node.child == nil or node.tag == HostPortal then\
\9\9\9\9continueOuter = true\
\9\9\9\9break\
\9\9\9else\
\9\9\9\9(node.child :: Fiber).return_ = node\
\9\9\9\9node = node.child :: Fiber\
\9\9\9end\
\9\9end\
\9\9if continueOuter then\
\9\9\9continue\
\9\9end\
\9\9-- Check if this host node is stable or about to be placed.\
\9\9if bit32.band(node.flags, Placement) == 0 then\
\9\9\9-- Found it!\
\9\9\9return node.stateNode\
\9\9end\
\9end\
end\
\
local function commitPlacement(finishedWork: Fiber)\
\9if not supportsMutation then\
\9\9return\
\9end\
\
\9-- Recursively insert all host nodes into the parent.\
\9local parentFiber = getHostParentFiber(finishedWork)\
\
\9-- Note: these two variables *must* always be updated together.\
\9local parent\
\9local isContainer\
\9local parentStateNode = parentFiber.stateNode\
\9if parentFiber.tag == HostComponent then\
\9\9parent = parentStateNode\
\9\9isContainer = false\
\9elseif parentFiber.tag == HostRoot then\
\9\9parent = parentStateNode.containerInfo\
\9\9isContainer = true\
\9elseif parentFiber.tag == HostPortal then\
\9\9parent = parentStateNode.containerInfo\
\9\9isContainer = true\
\9-- elseif parentFiber.tag == FundamentalComponent then\
\9--   if enableFundamentalAPI then\
\9--     parent = parentStateNode.instance\
\9--     isContainer = false\
\9--   end\
\9else\
\9\9-- eslint-disable-next-line-no-fallthrough\
\9\9invariant(\
\9\9\9false,\
\9\9\9\"Invalid host parent fiber. This error is likely caused by a bug \"\
\9\9\9\9.. \"in React. Please file an issue.\"\
\9\9)\
\9end\
\9if bit32.band(parentFiber.flags, ContentReset) ~= 0 then\
\9\9-- Reset the text content of the parent before doing any insertions\
\9\9resetTextContent(parent)\
\9\9-- Clear ContentReset from the effect tag\
\9\9parentFiber.flags = bit32.band(parentFiber.flags, bit32.bnot(ContentReset))\
\9end\
\
\9local before\
\9if skipHostSiblingLookup then\
\9\9-- ROBLOX performance: the host ignores insertion order, so no sibling is needed\
\9\9before = nil\
\9else\
\9\9before = getHostSibling(finishedWork)\
\9end\
\9-- We only have the top Fiber that was inserted but we need to recurse down its\
\9-- children to find all the terminal nodes.\
\9if isContainer then\
\9\9insertOrAppendPlacementNodeIntoContainer(finishedWork, before, parent)\
\9else\
\9\9insertOrAppendPlacementNode(finishedWork, before, parent)\
\9end\
end\
\
function insertOrAppendPlacementNodeIntoContainer(\
\9node: Fiber,\
\9before: Instance?,\
\9parent: Container\
)\
\9local tag = node.tag\
\9local isHost = tag == HostComponent or tag == HostText\
\9-- ROBLOX performance: avoid always-false compare for Roblox renderer in hot path\
\9if isHost then -- or (enableFundamentalAPI and tag == FundamentalComponent) then\
\9\9local stateNode = node.stateNode\
\9\9if before then\
\9\9\9insertInContainerBefore(parent, stateNode, before)\
\9\9else\
\9\9\9appendChildToContainer(parent, stateNode)\
\9\9end\
\9elseif tag == HostPortal then\
\9-- If the insertion itself is a portal, then we don't want to traverse\
\9-- down its children. Instead, we'll get insertions from each child in\
\9-- the portal directly.\
\9else\
\9\9local child = node.child\
\9\9if child ~= nil then\
\9\9\9insertOrAppendPlacementNodeIntoContainer(child, before, parent)\
\9\9\9local sibling = child.sibling\
\9\9\9while sibling ~= nil do\
\9\9\9\9insertOrAppendPlacementNodeIntoContainer(sibling, before, parent)\
\9\9\9\9sibling = sibling.sibling\
\9\9\9end\
\9\9end\
\9end\
end\
\
function insertOrAppendPlacementNode(node: Fiber, before: Instance?, parent: Instance): ()\
\9local tag = node.tag\
\9local isHost = tag == HostComponent or tag == HostText\
\9-- ROBLOX performance: avoid always-false compare for Roblox renderer in hot path\
\9if isHost then -- or (enableFundamentalAPI and tag == FundamentalComponent) then\
\9\9local stateNode = node.stateNode\
\9\9if before then\
\9\9\9insertBefore(parent, stateNode, before)\
\9\9else\
\9\9\9appendChild(parent, stateNode)\
\9\9end\
\9elseif tag == HostPortal then\
\9-- If the insertion itself is a portal, then we don't want to traverse\
\9-- down its children. Instead, we'll get insertions from each child in\
\9-- the portal directly.\
