\9\9--   -- -- Delete the dehydrated suspense boundary and all of its content.\
\9\9--   -- if currentParentIsContainer)\
\9\9--   --   clearSuspenseBoundaryFromContainer(\
\9\9--   --     ((currentParent: any): Container),\
\9\9--   --     (node.stateNode: SuspenseInstance),\
\9\9--   --   )\
\9\9--   -- } else {\
\9\9--   --   clearSuspenseBoundary(\
\9\9--   --     ((currentParent: any): Instance),\
