\9--   -- Detach refs and call componentWillUnmount() on the whole subtree.\
\9--   commitNestedUnmounts(\
\9--     finishedRoot,\
\9--     current,\
\9--     nearestMountedAncestor,\
\9--     renderPriorityLevel\
\9--   )\
\9-- end\
\9local alternate\
\9if not enableNewTreeCleanupPath then\
\9\9alternate = current.alternate\
\9end\
\9detachFiberMutation(current)\
\9if not enableNewTreeCleanupPath and alternate ~= nil then\
\9\9detachFiberMutation(alternate)\
\9end\
