\9if enableSuspenseCallback and newState ~= nil then\
\9\9local suspenseCallback = finishedWork.memoizedProps.suspenseCallback\
\9\9if typeof(suspenseCallback) == \"function\" then\
\9\9\9local wakeables: Set<Wakeable> | nil = finishedWork.updateQueue :: any\
\9\9\9if wakeables ~= nil then\
\9\9\9\9suspenseCallback(table.clone(wakeables))\
\9\9\9end\
\9\9elseif __DEV__ then\
\9\9\9if suspenseCallback ~= nil then\
\9\9\9\9console.error(\
\9\9\9\9\9\"Unexpected type for suspenseCallback: %s\",\
\9\9\9\9\9tostring(suspenseCallback)\
\9\9\9\9)\
\9\9\9end\
\9\9end\
\9end\
end\
