function commitSuspenseHydrationCallbacks(finishedRoot: FiberRoot, finishedWork: Fiber)\
\9if not supportsHydration then\
\9\9return\
\9end\
\9local newState: SuspenseState | nil = finishedWork.memoizedState\
\9if newState == nil then\
\9\9local current = finishedWork.alternate\
\9\9if current ~= nil then\
\9\9\9local prevState: SuspenseState | nil = current.memoizedState\
\9\9\9if prevState ~= nil then\
\9\9\9\9local suspenseInstance = prevState.dehydrated\
\9\9\9\9if suspenseInstance ~= nil then\
\9\9\9\9\9commitHydratedSuspenseInstance(suspenseInstance)\
\9\9\9\9\9if enableSuspenseCallback then\
\9\9\9\9\9\9local hydrationCallbacks = finishedRoot.hydrationCallbacks\
\9\9\9\9\9\9if hydrationCallbacks ~= nil then\
\9\9\9\9\9\9\9local onHydrated = hydrationCallbacks.onHydrated\
\9\9\9\9\9\9\9if onHydrated then\
\9\9\9\9\9\9\9\9onHydrated(suspenseInstance)\
\9\9\9\9\9\9\9end\
\9\9\9\9\9\9end\
\9\9\9\9\9end\
\9\9\9\9end\
\9\9\9end\
\9\9end\
\9end\
end\
\
function attachSuspenseRetryListeners(finishedWork: Fiber)\
\9-- If this boundary just timed out, then it will have a set of wakeables.\
\9-- For each wakeable, attach a listener so that when it resolves, React\
\9-- attempts to re-render the boundary in the primary (pre-timeout) state.\
\9local wakeables: Set<Wakeable> | nil = finishedWork.updateQueue :: any\
\9if wakeables ~= nil then\
\9\9finishedWork.updateQueue = nil\
\9\9local retryCache = finishedWork.stateNode\
\9\9if retryCache == nil then\
\9\9\9finishedWork.stateNode = Set.new()\
\9\9\9retryCache = finishedWork.stateNode\
\9\9end\
\9\9for wakeable, _ in wakeables :: Set<Wakeable> do\
\9\9\9-- Memoize using the boundary fiber to prevent redundant listeners.\
\9\9\9local retry = function()\
\9\9\9\9return resolveRetryWakeable(finishedWork, wakeable)\
\9\9\9end\
