local function updateWorkInProgressHook(): Hook\
\9-- This function is used both for updates and for re-renders triggered by a\
\9-- render phase update. It assumes there is either a current hook we can\
\9-- clone, or a work-in-progress hook from a previous render pass that we can\
\9-- use as a base. When we reach the end of the base list, we must switch to\
\9-- the dispatcher used for mounts.\
\9-- FIXME (roblox): type refinement\
\9-- local nextCurrentHook: Hook?\
\9local nextCurrentHook\
\9if currentHook == nil then\
\9\9local current = currentlyRenderingFiber.alternate\
\9\9if current ~= nil then\
\9\9\9nextCurrentHook = current.memoizedState\
\9\9else\
\9\9\9nextCurrentHook = nil\
\9\9end\
\9else\
\9\9nextCurrentHook = currentHook.next\
\9end\
\
\9-- FIXME (roblox): type refinement\
\9-- local nextWorkInProgressHook: Hook?\
\9local nextWorkInProgressHook: Hook\
\9if workInProgressHook == nil then\
\9\9nextWorkInProgressHook = currentlyRenderingFiber.memoizedState\
\9else\
\9\9nextWorkInProgressHook = workInProgressHook.next\
\9end\
\
\9if nextWorkInProgressHook ~= nil then\
\9\9-- There's already a work-in-progress. Reuse it.\
\9\9workInProgressHook = nextWorkInProgressHook\
\9\9nextWorkInProgressHook = workInProgressHook.next\
\
\9\9currentHook = nextCurrentHook\
\9else\
\9\9-- Clone from the current hook.\
\
\9\9-- ROBLOX performance: use React 18 check to avoid function call overhead\
\9\9if nextCurrentHook == nil then\
\9\9\9error(Error.new(\"Rendered more hooks than during the previous render.\"))\
\9\9end\
\
\9\9currentHook = nextCurrentHook\
\
\9\9local newHook: Hook\
\9\9if enableHookDoubleBuffering then\
\9\9\9-- ROBLOX performance: overwrite the hook at this position in the alternate\
\9\9\9-- fiber instead of allocating one each render\
\9\9\9newHook = currentHook.alternate\
\9\9\9if newHook ~= nil then\
\9\9\9\9-- Only assign nil to fields that are currently non-nil. Most hooks only hold\
\9\9\9\9-- memoizedState/next/alternate, and a rehash can shrink them to 4 hash nodes;\
\9\9\9\9-- unguarded nil copies then insert absent keys and rehash the hook again\
\9\9\9\9-- (see createWorkInProgress)\
\9\9\9\9local value = currentHook.memoizedState\
\9\9\9\9if value ~= nil or newHook.memoizedState ~= nil then\
\9\9\9\9\9newHook.memoizedState = value\
\9\9\9\9end\
\9\9\9\9value = currentHook.baseState\
\9\9\9\9if value ~= nil or newHook.baseState ~= nil then\
\9\9\9\9\9newHook.baseState = value\
\9\9\9\9end\
\9\9\9\9value = currentHook.baseQueue\
\9\9\9\9if value ~= nil or newHook.baseQueue ~= nil then\
\9\9\9\9\9newHook.baseQueue = value\
\9\9\9\9end\
\9\9\9\9value = currentHook.queue\
\9\9\9\9if value ~= nil or newHook.queue ~= nil then\
\9\9\9\9\9newHook.queue = value\
\9\9\9\9end\
\9\9\9\9if newHook.next ~= nil then\
\9\9\9\9\9newHook.next = nil\
\9\9\9\9end\
\9\9\9else\
\9\9\9\9newHook = {\
\9\9\9\9\9memoizedState = currentHook.memoizedState,\
\9\9\9\9\9baseState = currentHook.baseState,\
\9\9\9\9\9baseQueue = currentHook.baseQueue,\
\9\9\9\9\9queue = currentHook.queue,\
\9\9\9\9\9next = nil,\
\9\9\9\9}\
\9\9\9\9newHook.alternate = currentHook\
\9\9\9\9currentHook.alternate = newHook\
\9\9\9end\
\9\9else\
\9\9\9if enableAllocationTrims then\
\9\9\9\9-- ROBLOX performance: only list baseQueue when it's set, so that the\
\9\9\9\9-- common case fits in 4 hash slots instead of 8 (see mountWorkInProgressHook)\
\9\9\9\9local baseQueue = currentHook.baseQueue\
\9\9\9\9if baseQueue == nil then\
\9\9\9\9\9newHook = {\
\9\9\9\9\9\9memoizedState = currentHook.memoizedState,\
\9\9\9\9\9\9baseState = currentHook.baseState,\
\9\9\9\9\9\9queue = currentHook.queue,\
\9\9\9\9\9\9next = nil,\
\9\9\9\9\9}\
\9\9\9\9else\
\9\9\9\9\9newHook = {\
\9\9\9\9\9\9memoizedState = currentHook.memoizedState,\
\9\9\9\9\9\9baseState = currentHook.baseState,\
\9\9\9\9\9\9baseQueue = baseQueue,\
\9\9\9\9\9\9queue = currentHook.queue,\
\9\9\9\9\9\9next = nil,\
\9\9\9\9\9}\
\9\9\9\9end\
\9\9\9else\
\9\9\9\9newHook = {\
\9\9\9\9\9memoizedState = currentHook.memoizedState,\
\
\9\9\9\9\9baseState = currentHook.baseState,\
\9\9\9\9\9baseQueue = currentHook.baseQueue,\
\9\9\9\9\9queue = currentHook.queue,\
\
\9\9\9\9\9next = nil,\
\9\9\9\9}\
\9\9\9end\
\9\9end\
\
\9\9if workInProgressHook == nil then\
\9\9\9-- This is the first hook in the list.\
\9\9\9workInProgressHook = newHook\
\9\9\9currentlyRenderingFiber.memoizedState = newHook\
\9\9else\
\9\9\9-- Append to the end of the list.\
\9\9\9workInProgressHook.next = newHook\
\9\9\9workInProgressHook = newHook\
\9\9end\
\9end\
