\9local hook = mountWorkInProgressHook()\
\9local initialState\
\9if init ~= nil then\
\9\9initialState = init(initialArg)\
\9else\
\9\9initialState = (initialArg :: any) :: S\
\9end\
\9hook.baseState = initialState\
\9hook.memoizedState = hook.baseState\
