\9local queue: UpdateQueue<S, A> = {\
\9\9pending = nil,\
\9\9dispatch = nil,\
\9\9lastRenderedReducer = reducer,\
\9\9lastRenderedState = initialState :: any,\
\9}\
\9hook.queue = queue\
