\9\9--   if current.baseQueue ~= baseQueue then\
\9\9--     -- Internal invariant that should never happen, but feasibly could in\
\9\9--     -- the future if we implement resuming, or some form of that.\
\9\9--     console.error(\
\9\9--       'Internal error: Expected work-in-progress queue to be a clone. ' ..\
\9\9--         'This is a bug in React.'\
\9\9--     )\
\9\9--   end\
\9\9-- end\
\9\9baseQueue = pendingQueue\
\9\9current.baseQueue = baseQueue\
\9\9queue.pending = nil\
\9end\
\
\9if baseQueue ~= nil then\
\9\9-- We have a queue to process.\
\9\9local first = baseQueue.next\
\9\9local newState = current.baseState\
\
\9\9local newBaseState = nil\
\9\9local newBaseQueueFirst = nil\
\9\9local newBaseQueueLast = nil\
\9\9local update = first\
\9\9repeat\
\9\9\9local updateLane = update.lane\
\9\9\9-- ROBLOX performance: inline isSubsetOfLanes for hot path\
\9\9\9-- if not isSubsetOfLanes(renderLanes, updateLane) then\
\9\9\9if bit32.band(renderLanes, updateLane) ~= updateLane then\
\9\9\9\9-- Priority is insufficient. Skip this update. If this is the first\
\9\9\9\9-- skipped update, the previous update/state is the new base\
\9\9\9\9-- update/state.\
\9\9\9\9local clone: Update<S, A> = {\
\9\9\9\9\9lane = updateLane,\
\9\9\9\9\9action = update.action,\
\9\9\9\9\9eagerReducer = update.eagerReducer,\
\9\9\9\9\9eagerState = update.eagerState,\
\9\9\9\9\9next = nil :: any,\
\9\9\9\9}\
\9\9\9\9if newBaseQueueLast == nil then\
\9\9\9\9\9newBaseQueueLast = clone\
\9\9\9\9\9newBaseQueueFirst = newBaseQueueLast\
\9\9\9\9\9newBaseState = newState\
\9\9\9\9else\
\9\9\9\9\9newBaseQueueLast.next = clone\
\9\9\9\9\9newBaseQueueLast = newBaseQueueLast.next\
\9\9\9\9end\
\9\9\9\9-- Update the remaining priority in the queue.\
\9\9\9\9-- TODO: Don't need to accumulate this. Instead, we can remove\
\9\9\9\9-- renderLanes from the original lanes.\
\9\9\9\9currentlyRenderingFiber.lanes =\
\9\9\9\9\9mergeLanes(currentlyRenderingFiber.lanes, updateLane)\
