\9\9\9\9-- Process this update.\
\9\9\9\9if update.eagerReducer == reducer then\
\9\9\9\9\9-- If this update was processed eagerly, and its reducer matches the\
\9\9\9\9\9-- current reducer, we can use the eagerly computed state.\
\9\9\9\9\9newState = update.eagerState\
\9\9\9\9else\
\9\9\9\9\9local action = update.action\
\9\9\9\9\9newState = reducer(newState, action)\
\9\9\9\9end\
\9\9\9end\
\9\9\9update = update.next\
\9\9until update == nil or update == first\
\
\9\9if newBaseQueueLast == nil then\
\9\9\9newBaseState = newState\
\9\9else\
\9\9\9newBaseQueueLast.next = newBaseQueueFirst\
\9\9end\
\
\9\9-- Mark that the fiber performed work, but only if the new state is\
\9\9-- different from the current state.\
\9\9if not is(newState, hook.memoizedState) then\
\9\9\9markWorkInProgressReceivedUpdate()\
\9\9end\
\
\9\9hook.memoizedState = newState\
\9\9hook.baseState = newBaseState\
\9\9hook.baseQueue = newBaseQueueLast\
\
\9\9queue.lastRenderedState = newState\
\9end\
\
\9local dispatch: Dispatch<A> = queue.dispatch :: any\
\9-- deviation: Lua version of useState and useReducer return two items, not list like upstream\
\9return hook.memoizedState, dispatch\
end\
\
function rerenderReducer<S, I, A>(\
\9reducer: (S, A) -> S,\
\9initialArg: I,\
\9init: ((I) -> S)?\
): (S, Dispatch<A>)\
\9local hook = updateWorkInProgressHook()\
\9local queue = hook.queue\
\9-- ROBLOX performance: changed from invariant to avoid function call in hot path\
\9assert(\
\9\9queue ~= nil,\
\9\9\"Should have a queue. This is likely a bug in React. Please file an issue.\"\
\9)\
\
\9queue.lastRenderedReducer = reducer\
\
\9-- This is a re-render. Apply the new render phase updates to the previous\
\9-- work-in-progress hook.\
\9local dispatch: Dispatch<A> = queue.dispatch :: Dispatch<A>\
\9local lastRenderPhaseUpdate = queue.pending\
\9local newState = hook.memoizedState\
\9if lastRenderPhaseUpdate ~= nil then\
\9\9-- The queue doesn't persist past this render pass.\
\9\9queue.pending = nil\
\
\9\9local firstRenderPhaseUpdate = lastRenderPhaseUpdate.next\
\9\9local update = firstRenderPhaseUpdate\
\9\9repeat\
\9\9\9-- Process this render phase update. We don't have to check the\
\9\9\9-- priority because it will always be the same as the current\
\9\9\9-- render's.\
\9\9\9local action = update.action\
\9\9\9newState = reducer(newState, action)\
\9\9\9update = update.next\
\9\9until update == firstRenderPhaseUpdate\
\
\9\9-- Mark that the fiber performed work, but only if the new state is\
\9\9-- different from the current state.\
\9\9if not is(newState, hook.memoizedState) then\
\9\9\9markWorkInProgressReceivedUpdate()\
\9\9end\
\
\9\9hook.memoizedState = newState\
\9\9-- Don't persist the state accumulated from the render phase updates to\
\9\9-- the base state unless the queue is empty.\
\9\9-- TODO: Not sure if this is the desired semantics, but it's what we\
\9\9-- do for gDSFP. I can't remember why.\
\9\9if hook.baseQueue == nil then\
\9\9\9hook.baseState = newState\
\9\9end\
\
\9\9queue.lastRenderedState = newState\
\9end\
\9-- ROBLOX deviation: Lua version returns two values instead of an array\
\9return newState, dispatch\
end\
