type MutableSourceMemoizedState<Source, Snapshot> = {\
\9refs: {\
\9\9getSnapshot: MutableSourceGetSnapshotFn<Source, Snapshot>,\
\9\9setSnapshot: (Snapshot) -> (),\
\9},\
\9source: MutableSource<any>,\
\9subscribe: MutableSourceSubscribeFn<Source, Snapshot>,\
}\
