function readFromUnsubcribedMutableSource<Source, Snapshot>(\
\9root: FiberRoot,\
\9source: MutableSource<Source>,\
\9getSnapshot: MutableSourceGetSnapshotFn<\
\9\9Source,\
\9\9Snapshot\
\9>\
): Snapshot\
\9if __DEV__ then\
\9\9warnAboutMultipleRenderersDEV(source)\
\9end\
