exports.requestEventTime = function()\
\9if\
\9\9bit32.band(executionContext, bit32.bor(RenderContext, CommitContext))\
\9\9~= NoContext\
\9then\
\9\9-- We're inside React, so it's fine to read the actual time.\
\9\9return now()\
\9end\
\9-- We're not inside React, so we may be in the middle of a browser event.\
\9if currentEventTime ~= NoTimestamp then\
\9\9-- Use the same start time for all updates until we enter React again.\
\9\9return currentEventTime\
\9end\
\9-- This is the first update since React yielded. Compute a new start time.\
\9currentEventTime = now()\
\9return currentEventTime\
end\
