function requestRetryLane(fiber: Fiber): Lane\
\9-- This is a fork of `requestUpdateLane` designed specifically for Suspense\
\9-- \"retries\" — a special update that attempts to flip a Suspense boundary\
\9-- from its placeholder state to its primary/resolved state.\
\
\9-- Special cases\
\9local mode = fiber.mode\
\9if bit32.band(mode, ReactTypeOfMode.BlockingMode) == ReactTypeOfMode.NoMode then\
\9\9return SyncLane :: Lane\
\9elseif bit32.band(mode, ReactTypeOfMode.ConcurrentMode) == ReactTypeOfMode.NoMode then\
\9\9return if getCurrentPriorityLevel() == ImmediateSchedulerPriority\
\9\9\9then SyncLane :: Lane\
\9\9\9else SyncBatchedLane :: Lane\
\9end\
\
\9-- See `requestUpdateLane` for explanation of `currentEventWipLanes`\
\9if currentEventWipLanes == ReactFiberLane.NoLanes then\
\9\9currentEventWipLanes = workInProgressRootIncludedLanes\
\9end\
\9return findRetryLane(currentEventWipLanes)\
end\
