mod.markUpdateLaneFromFiberToRoot = function(sourceFiber: Fiber, lane: Lane): FiberRoot?\
\9-- Update the source fiber's lanes\
\9sourceFiber.lanes = mergeLanes(sourceFiber.lanes, lane)\
\9local alternate = sourceFiber.alternate\
\9if alternate ~= nil then\
\9\9alternate.lanes = mergeLanes(alternate.lanes, lane)\
\9end\
\9if __DEV__ then\
\9\9if\
\9\9\9alternate == nil\
\9\9\9and bit32.band(\
\9\9\9\9\9sourceFiber.flags,\
\9\9\9\9\9bit32.bor(ReactFiberFlags.Placement, ReactFiberFlags.Hydrating)\
\9\9\9\9)\
\9\9\9\9~= ReactFiberFlags.NoFlags\
