\9\9if existingCallbackNode ~= nil then\
\9\9\9cancelCallback(existingCallbackNode)\
\9\9\9root.callbackNode = nil\
\9\9\9root.callbackPriority = ReactFiberLane.NoLanePriority\
\9\9end\
\9\9return\
\9end\
