mod.commitMutationEffectsImpl = function(\
\9fiber: Fiber,\
\9root: FiberRoot,\
\9renderPriorityLevel\
)\
\9local flags = fiber.flags\
\9-- ROBLOX performance: avoid always-false compare for Roblox renderer in hot path\
\9-- if bit32.band(flags, ReactFiberFlags.ContentReset) ~= 0 then\
\9--   unimplemented(\"commitResetTextContent\")\
\9-- commitResetTextContent(fiber)\
\9-- end\
\
\9if bit32.band(flags, ReactFiberFlags.Ref) ~= 0 then\
\9\9local current = fiber.alternate\
\9\9if current ~= nil then\
\9\9\9commitDetachRef(current)\
\9\9end\
\9\9-- ROBLOX performance: avoid always-false compare for Roblox renderer in hot path\
\9\9-- if ReactFeatureFlags.enableScopeAPI then\
\9\9--   -- TODO: This is a temporary solution that allowed us to transition away from React Flare on www.\
\9\9--   if fiber.tag == ReactWorkTags.ScopeComponent then\
\9\9--     commitAttachRef(fiber)\
\9\9--   end\
\9\9-- end\
\9end\
\
\9-- The following switch statement is only concerned about placement,\
\9-- updates, and deletions. To avoid needing to add a case for every possible\
\9-- bitmap value, we remove the secondary effects from the effect tag and\
\9-- switch on that value.\
\9local primaryFlags = bit32.band(\
\9\9flags,\
\9\9bit32.bor(\
\9\9\9ReactFiberFlags.Placement,\
\9\9\9ReactFiberFlags.Update,\
\9\9\9ReactFiberFlags.Hydrating\
\9\9)\
\9)\
\9if ReactFeatureFlags.enableCommitTraversalTrims then\
\9\9-- ROBLOX deviation: HostUpdate is committed exactly like Update\
\9\9if bit32.band(flags, ReactFiberFlags.HostUpdate) ~= ReactFiberFlags.NoFlags then\
\9\9\9primaryFlags = bit32.bor(primaryFlags, ReactFiberFlags.Update)\
\9\9end\
\9end\
\9if primaryFlags == ReactFiberFlags.Placement then\
\9\9commitPlacement(fiber)\
\9\9-- Clear the \"placement\" from effect tag so that we know that this is\
\9\9-- inserted, before any life-cycles like componentDidMount gets called.\
\9\9-- TODO: findDOMNode doesn't rely on this any more but isMounted does\
\9\9-- and isMounted is deprecated anyway so we should be able to kill this.\
\9\9fiber.flags = bit32.band(fiber.flags, bit32.bnot(ReactFiberFlags.Placement))\
\9elseif primaryFlags == ReactFiberFlags.PlacementAndUpdate then\
\9\9-- Placement\
\9\9commitPlacement(fiber)\
\9\9-- Clear the \"placement\" from effect tag so that we know that this is\
\9\9-- inserted, before any life-cycles like componentDidMount gets called.\
\9\9fiber.flags = bit32.band(fiber.flags, bit32.bnot(ReactFiberFlags.Placement))\
\
\9\9-- Update\
\9\9local current = fiber.alternate\
\9\9commitWork(current, fiber)\
\9\9-- ROBLOX performance: avoid always-false compare for Roblox renderer in hot path\
\9\9-- elseif primaryFlags == ReactFiberFlags.Hydrating then\
\9\9--   fiber.flags = bit32.band(fiber.flags, bit32.bnot(ReactFiberFlags.Hydrating))\
\9\9-- elseif primaryFlags == ReactFiberFlags.HydratingAndUpdate then\
\9\9--   fiber.flags = bit32.band(fiber.flags, bit32.bnot(ReactFiberFlags.Hydrating))\
\9\9--   -- Update\
\9\9--   local current = fiber.alternate\
\9\9--   commitWork(current, fiber)\
\9elseif primaryFlags == ReactFiberFlags.Update then\
\9\9local current = fiber.alternate\
\9\9commitWork(current, fiber)\
\9end\
end\
