exports.schedulePassiveEffectCallback = function()\
\9if not rootDoesHavePassiveEffects then\
\9\9rootDoesHavePassiveEffects = true\
\9\9scheduleCallback(NormalSchedulerPriority, function()\
\9\9\9exports.flushPassiveEffects()\
\9\9\9return nil\
\9\9end)\
\9end\
end\
\
-- deviation: Pre-declare functions\
local flushPassiveEffectsImpl\
exports.flushPassiveEffects = function(): boolean\
\9-- Returns whether passive effects were flushed.\
\9if pendingPassiveEffectsRenderPriority ~= NoSchedulerPriority then\
\9\9local priorityLevel = if pendingPassiveEffectsRenderPriority\
\9\9\9\9> NormalSchedulerPriority\
\9\9\9then NormalSchedulerPriority\
\9\9\9else pendingPassiveEffectsRenderPriority\
\9\9pendingPassiveEffectsRenderPriority = NoSchedulerPriority\
\9\9if ReactFeatureFlags.decoupleUpdatePriorityFromScheduler then\
\9\9\9local previousLanePriority = getCurrentUpdateLanePriority()\
\
\9\9\9-- ROBLOX performance: extract non-throwable function from try{} to remove need for anon function\
\9\9\9setCurrentUpdateLanePriority(schedulerPriorityToLanePriority(priorityLevel))\
\9\9\9-- ROBLOX deviation: YOLO flag for disabling pcall\
\9\9\9local ok, result\
\9\9\9if not __YOLO__ then\
\9\9\9\9ok, result = xpcall(\
\9\9\9\9\9runWithPriority,\
\9\9\9\9\9describeError,\
\9\9\9\9\9priorityLevel,\
\9\9\9\9\9flushPassiveEffectsImpl\
\9\9\9\9)\
\9\9\9else\
\9\9\9\9ok = true\
\9\9\9\9setCurrentUpdateLanePriority(\
\9\9\9\9\9schedulerPriorityToLanePriority(priorityLevel)\
\9\9\9\9)\
\9\9\9\9result = runWithPriority(priorityLevel, flushPassiveEffectsImpl)\
\9\9\9end\
\
\9\9\9-- finally\
\9\9\9setCurrentUpdateLanePriority(previousLanePriority)\
\
\9\9\9if not ok then\
\9\9\9\9error(result)\
\9\9\9end\
\9\9\9return result\
\9\9else\
\9\9\9return runWithPriority(priorityLevel, flushPassiveEffectsImpl)\
\9\9end\
\9end\
\9return false\
end\
