flushPassiveMountEffects = function(root, firstChild: Fiber): ()\
\9local fiber = firstChild\
\9while fiber ~= nil do\
\9\9local prevProfilerOnStack = nil\
\9\9if\
\9\9\9ReactFeatureFlags.enableProfilerTimer\
\9\9\9and ReactFeatureFlags.enableProfilerCommitHooks\
\9\9then\
\9\9\9if fiber.tag == ReactWorkTags.Profiler then\
\9\9\9\9prevProfilerOnStack = nearestProfilerOnStack\
\9\9\9\9nearestProfilerOnStack = fiber\
\9\9\9end\
\9\9end\
