\9\9local primarySubtreeFlags =\
\9\9\9bit32.band(fiber.subtreeFlags, ReactFiberFlags.PassiveMask)\
\
\9\9if fiber.child ~= nil and primarySubtreeFlags ~= ReactFiberFlags.NoFlags then\
\9\9\9flushPassiveMountEffects(root, fiber.child)\
\9\9end\
\
\9\9if\
\9\9\9bit32.band(fiber.flags, ReactFiberFlags.Passive) ~= ReactFiberFlags.NoFlags\
\9\9then\
\9\9\9if __DEV__ then\
\9\9\9\9setCurrentDebugFiberInDEV(fiber)\
\9\9\9\9invokeGuardedCallback(nil, commitPassiveMountOnFiber, nil, root, fiber)\
\9\9\9\9if hasCaughtError() then\
\9\9\9\9\9local error_ = clearCaughtError()\
\9\9\9\9\9exports.captureCommitPhaseError(fiber, fiber.return_, error_)\
\9\9\9\9end\
\9\9\9\9resetCurrentDebugFiberInDEV()\
\9\9\9else\
\9\9\9\9-- ROBLOX deviation: YOLO flag for disabling pcall\
\9\9\9\9local ok, error_\
\9\9\9\9if not __YOLO__ then\
\9\9\9\9\9ok, error_ =\
\9\9\9\9\9\9xpcall(commitPassiveMountOnFiber, describeError, root, fiber)\
\9\9\9\9else\
\9\9\9\9\9ok = true\
\9\9\9\9\9commitPassiveMountOnFiber(root, fiber)\
\9\9\9\9end\
\
\9\9\9\9if not ok then\
\9\9\9\9\9exports.captureCommitPhaseError(fiber, fiber.return_, error_)\
\9\9\9\9end\
\9\9\9end\
\9\9end\
\
\9\9if\
\9\9\9ReactFeatureFlags.enableProfilerTimer\
\9\9\9and ReactFeatureFlags.enableProfilerCommitHooks\
\9\9then\
\9\9\9if fiber.tag == ReactWorkTags.Profiler then\
\9\9\9\9-- Bubble times to the next nearest ancestor Profiler.\
\9\9\9\9-- After we process that Profiler, we'll bubble further up.\
\9\9\9\9if prevProfilerOnStack ~= nil then\
\9\9\9\9\9prevProfilerOnStack.stateNode.passiveEffectDuration += fiber.stateNode.passiveEffectDuration\
\9\9\9\9end\
\
\9\9\9\9nearestProfilerOnStack = prevProfilerOnStack\
\9\9\9end\
\9\9end\
\
\9\9-- ROBLOX Luau FIXME: Luau doesn't understand the loop ~= nil construct\
\9\9fiber = fiber.sibling :: Fiber\
\9end\
end\
