\9\9\9else\
\9\9\9\9ok = true\
\9\9\9\9commitPassiveMountOnFiber(root, fiber)\
\9\9\9end\
\
\9\9\9if not ok then\
\9\9\9\9exports.captureCommitPhaseError(fiber, fiber.return_, error_)\
