local function flushPassiveUnmountEffects(firstChild: Fiber): ()\
\9local fiber = firstChild\
\9while fiber ~= nil do\
\9\9local deletions = fiber.deletions\
\9\9if deletions ~= nil then\
\9\9\9for i = 1, #deletions do\
\9\9\9\9local fiberToDelete = deletions[i]\
\9\9\9\9mod.flushPassiveUnmountEffectsInsideOfDeletedTree(fiberToDelete, fiber)\
\
\9\9\9\9if not (enableNewTreeCleanupPath and deletedTreeCleanUpLevel >= 2) then\
\9\9\9\9\9-- Now that passive effects have been processed, it's safe to detach lingering pointers.\
\9\9\9\9\9mod.detachFiberAfterEffects(fiberToDelete)\
\9\9\9\9end\
\9\9\9end\
\
\9\9\9if enableNewTreeCleanupPath then\
\9\9\9\9if deletedTreeCleanUpLevel >= 1 then\
\9\9\9\9\9-- A fiber was deleted from this parent fiber, but it's still part of\
\9\9\9\9\9-- the previous (alternate) parent fiber's list of children. Because\
\9\9\9\9\9-- children are a linked list, an earlier sibling that's still alive\
\9\9\9\9\9-- will be connected to the deleted fiber via its `alternate`:\
\9\9\9\9\9--\
\9\9\9\9\9--   live fiber\
\9\9\9\9\9--   --alternate--> previous live fiber\
\9\9\9\9\9--   --sibling--> deleted fiber\
\9\9\9\9\9--\
\9\9\9\9\9-- We can't disconnect `alternate` on nodes that haven't been deleted\
\9\9\9\9\9-- yet, but we can disconnect the `sibling` and `child` pointers.\
\9\9\9\9\9local previousFiber = fiber.alternate\
\9\9\9\9\9if previousFiber ~= nil then\
\9\9\9\9\9\9local detachedChild = previousFiber.child\
\9\9\9\9\9\9if detachedChild ~= nil then\
\9\9\9\9\9\9\9previousFiber.child = nil\
\9\9\9\9\9\9\9repeat\
\9\9\9\9\9\9\9\9local detachedSibling = detachedChild.sibling\
\9\9\9\9\9\9\9\9detachedChild.sibling = nil\
\9\9\9\9\9\9\9\9detachedChild = detachedSibling\
\9\9\9\9\9\9\9until detachedChild == nil\
\9\9\9\9\9\9end\
\9\9\9\9\9end\
\9\9\9\9end\
\9\9\9end\
\9\9end\
\
\9\9local child = fiber.child\
\9\9if child ~= nil then\
\9\9\9-- If any children have passive effects then traverse the subtree.\
\9\9\9-- Note that this requires checking subtreeFlags of the current Fiber,\
\9\9\9-- rather than the subtreeFlags/effectsTag of the first child,\
\9\9\9-- since that would not cover passive effects in siblings.\
\9\9\9local passiveFlags =\
\9\9\9\9bit32.band(fiber.subtreeFlags, ReactFiberFlags.PassiveMask)\
\9\9\9if passiveFlags ~= ReactFiberFlags.NoFlags then\
\9\9\9\9flushPassiveUnmountEffects(child)\
\9\9\9end\
\9\9end\
\
\9\9local primaryFlags = bit32.band(fiber.flags, ReactFiberFlags.Passive)\
\9\9if primaryFlags ~= ReactFiberFlags.NoFlags then\
\9\9\9setCurrentDebugFiberInDEV(fiber)\
\9\9\9commitPassiveUnmountOnFiber(fiber)\
\9\9\9resetCurrentDebugFiberInDEV()\
\9\9end\
\
\9\9-- ROBLOX FIXME Luau: Luau doesn't understand the loop ~= nil construct\
\9\9fiber = fiber.sibling :: Fiber\
\9end\
end\
\
-- ROBLOX performance: flushPassiveUnmountEffects that also collects the Passive fibers it visits, in\
-- order, so the mount pass can commit them without walking the tree again (ReactCommitTraversalTrims)\
mod.flushPassiveUnmountEffectsCollecting = function(\
\9firstChild: Fiber,\
\9passiveFibers: Array<Fiber>\
): ()\
\9local fiber = firstChild\
\9while fiber ~= nil do\
\9\9local deletions = fiber.deletions\
\9\9if deletions ~= nil then\
\9\9\9for i = 1, #deletions do\
\9\9\9\9local fiberToDelete = deletions[i]\
\9\9\9\9mod.flushPassiveUnmountEffectsInsideOfDeletedTree(fiberToDelete, fiber)\
\
\9\9\9\9if not (enableNewTreeCleanupPath and deletedTreeCleanUpLevel >= 2) then\
\9\9\9\9\9-- Now that passive effects have been processed, it's safe to detach lingering pointers.\
\9\9\9\9\9mod.detachFiberAfterEffects(fiberToDelete)\
\9\9\9\9end\
\9\9\9end\
\
\9\9\9if enableNewTreeCleanupPath then\
\9\9\9\9if deletedTreeCleanUpLevel >= 1 then\
\9\9\9\9\9-- A fiber was deleted from this parent fiber, but it's still part of\
\9\9\9\9\9-- the previous (alternate) parent fiber's list of children. Because\
\9\9\9\9\9-- children are a linked list, an earlier sibling that's still alive\
\9\9\9\9\9-- will be connected to the deleted fiber via its `alternate`:\
\9\9\9\9\9--\
\9\9\9\9\9--   live fiber\
\9\9\9\9\9--   --alternate--> previous live fiber\
\9\9\9\9\9--   --sibling--> deleted fiber\
\9\9\9\9\9--\
\9\9\9\9\9-- We can't disconnect `alternate` on nodes that haven't been deleted\
\9\9\9\9\9-- yet, but we can disconnect the `sibling` and `child` pointers.\
\9\9\9\9\9local previousFiber = fiber.alternate\
\9\9\9\9\9if previousFiber ~= nil then\
\9\9\9\9\9\9local detachedChild = previousFiber.child\
\9\9\9\9\9\9if detachedChild ~= nil then\
\9\9\9\9\9\9\9previousFiber.child = nil\
\9\9\9\9\9\9\9repeat\
\9\9\9\9\9\9\9\9local detachedSibling = detachedChild.sibling\
\9\9\9\9\9\9\9\9detachedChild.sibling = nil\
\9\9\9\9\9\9\9\9detachedChild = detachedSibling\
\9\9\9\9\9\9\9until detachedChild == nil\
\9\9\9\9\9\9end\
\9\9\9\9\9end\
\9\9\9\9end\
\9\9\9end\
\9\9end\
\
\9\9local child = fiber.child\
\9\9if child ~= nil then\
\9\9\9-- If any children have passive effects then traverse the subtree.\
\9\9\9-- Note that this requires checking subtreeFlags of the current Fiber,\
\9\9\9-- rather than the subtreeFlags/effectsTag of the first child,\
\9\9\9-- since that would not cover passive effects in siblings.\
\9\9\9local passiveFlags =\
\9\9\9\9bit32.band(fiber.subtreeFlags, ReactFiberFlags.PassiveMask)\
\9\9\9if passiveFlags ~= ReactFiberFlags.NoFlags then\
\9\9\9\9mod.flushPassiveUnmountEffectsCollecting(child, passiveFibers)\
\9\9\9end\
\9\9end\
\
\9\9local primaryFlags = bit32.band(fiber.flags, ReactFiberFlags.Passive)\
\9\9if primaryFlags ~= ReactFiberFlags.NoFlags then\
\9\9\9table.insert(passiveFibers, fiber)\
\9\9\9setCurrentDebugFiberInDEV(fiber)\
\9\9\9commitPassiveUnmountOnFiber(fiber)\
\9\9\9resetCurrentDebugFiberInDEV()\
\9\9end\
\
\9\9-- ROBLOX FIXME Luau: Luau doesn't understand the loop ~= nil construct\
\9\9fiber = fiber.sibling :: Fiber\
\9end\
end\
\
mod.flushPassiveUnmountEffectsInsideOfDeletedTree = function(\
\9fiberToDelete: Fiber,\
\9nearestMountedAncestor: Fiber\
)\
\9if\
\9\9bit32.band(fiberToDelete.subtreeFlags, ReactFiberFlags.PassiveStatic)\
\9\9\9~= ReactFiberFlags.NoFlags\
\9\9or (enableNewTreeCleanupPath and deletedTreeCleanUpLevel >= 2)\
\9then\
\9\9-- If any children have passive effects then traverse the subtree.\
\9\9-- Note that this requires checking subtreeFlags of the current Fiber,\
\9\9-- rather than the subtreeFlags/effectsTag of the first child,\
\9\9-- since that would not cover passive effects in siblings.\
\9\9local child = fiberToDelete.child\
\9\9while child ~= nil do\
\9\9\9local childSibling = child.sibling\
\9\9\9mod.flushPassiveUnmountEffectsInsideOfDeletedTree(\
\9\9\9\9child,\
\9\9\9\9nearestMountedAncestor\
\9\9\9)\
\9\9\9child = childSibling\
\9\9end\
\9end\
\
\9if\
\9\9bit32.band(fiberToDelete.flags, ReactFiberFlags.PassiveStatic)\
\9\9~= ReactFiberFlags.NoFlags\
\9then\
\9\9setCurrentDebugFiberInDEV(fiberToDelete)\
\9\9commitPassiveUnmountInsideDeletedTreeOnFiber(\
\9\9\9fiberToDelete,\
\9\9\9nearestMountedAncestor\
\9\9)\
\9\9resetCurrentDebugFiberInDEV()\
\9end\
\
\9if enableNewTreeCleanupPath and deletedTreeCleanUpLevel >= 2 then\
\9\9mod.detachFiberAfterEffects(fiberToDelete)\
\9end\
end\
\
flushPassiveEffectsImpl = function()\
\9if rootWithPendingPassiveEffects == nil then\
\9\9return false\
\9end\
\
\9-- ROBLOX Luau FIXME: Luau doesn't narrow to non-nil with the guard above\
\9local root = rootWithPendingPassiveEffects :: FiberRoot\
\9local lanes = pendingPassiveEffectsLanes\
\9rootWithPendingPassiveEffects = nil\
\9pendingPassiveEffectsLanes = ReactFiberLane.NoLanes\
\
\9invariant(\
\9\9bit32.band(executionContext, bit32.bor(RenderContext, CommitContext)) == NoContext,\
\9\9\"Cannot flush passive effects while already rendering.\"\
\9)\
\
\9if __DEV__ then\
\9\9if enableDebugTracing then\
\9\9\9DebugTracing.logPassiveEffectsStarted(lanes)\
\9\9end\
\9end\
\
\9if enableSchedulingProfiler then\
\9\9SchedulingProfiler.markPassiveEffectsStarted(lanes)\
\9end\
\
\9local prevExecutionContext = executionContext\
\9executionContext = bit32.bor(executionContext, CommitContext)\
\9local prevInteractions = mod.pushInteractions(root)\
\
\9-- It's important that ALL pending passive effect destroy functions are called\
\9-- before ANY passive effect create functions are called.\
\9-- Otherwise effects in sibling components might interfere with each other.\
\9-- e.g. a destroy function in one component may unintentionally override a ref\
\9-- value set by a create function in another component.\
\9-- Layout effects have the same constraint.\
\9if ReactFeatureFlags.enableCommitTraversalTrims then\
\9\9-- ROBLOX performance: unless Profilers need the tree walk to track durations, mount effects\
\9\9-- are committed from the Passive fibers collected by the unmount pass (same order)\
\9\9if\
\9\9\9not (\
\9\9\9\9ReactFeatureFlags.enableProfilerTimer\
\9\9\9\9and ReactFeatureFlags.enableProfilerCommitHooks\
\9\9\9)\
\9\9then\
\9\9\9local passiveFibers = mod.passiveMountFibers or {}\
\9\9\9mod.passiveMountFibers = nil\
\9\9\9mod.flushPassiveUnmountEffectsCollecting(root.current, passiveFibers)\
\9\9\9mod.commitPassiveMountEffectsOnFibers(root, passiveFibers)\
\9\9\9table.clear(passiveFibers)\
\9\9\9mod.passiveMountFibers = passiveFibers\
\9\9else\
\9\9\9flushPassiveUnmountEffects(root.current)\
\9\9\9flushPassiveMountEffects(root, root.current)\
\9\9end\
\9else\
\9\9flushPassiveUnmountEffects(root.current)\
\9\9flushPassiveMountEffects(root, root.current)\
\9end\
\
\9if __DEV__ then\
\9\9if enableDebugTracing then\
\9\9\9DebugTracing.logPassiveEffectsStopped()\
\9\9end\
\9end\
\
\9if enableSchedulingProfiler then\
\9\9-- ROBLOX deviation: pass root for attribution\
\9\9SchedulingProfiler.markPassiveEffectsStopped(root)\
\9end\
\
\9if __DEV__ and enableDoubleInvokingEffects then\
\9\9commitDoubleInvokeEffectsInDEV(root.current, true)\
\9end\
\
\9if ReactFeatureFlags.enableSchedulerTracing then\
\9\9mod.popInteractions(prevInteractions)\
\9\9mod.finishPendingInteractions(root, lanes)\
\9end\
\
\9executionContext = prevExecutionContext\
\
\9flushSyncCallbackQueue()\
\
\9-- If additional passive effects were scheduled, increment a counter. If this\
\9-- exceeds the limit, we'll fire a warning.\
\9if rootWithPendingPassiveEffects == nil then\
\9\9nestedPassiveUpdateCount = 0\
\9else\
\9\9nestedPassiveUpdateCount = nestedPassiveUpdateCount + 1\
\9end\
\
\9return true\
end\
\
exports.isAlreadyFailedLegacyErrorBoundary = function(instance): boolean\
\9return legacyErrorBoundariesThatAlreadyFailed ~= nil\
\9\9and legacyErrorBoundariesThatAlreadyFailed:has(instance)\
end\
\
exports.markLegacyErrorBoundaryAsFailed = function(instance)\
\9if legacyErrorBoundariesThatAlreadyFailed == nil then\
\9\9legacyErrorBoundariesThatAlreadyFailed = Set.new({ instance })\
\9else\
\9\9legacyErrorBoundariesThatAlreadyFailed:add(instance)\
\9end\
end\
\
-- ROBLOX TODO: this function and the related fields should be extracted/relocated to break a cycle\
local function prepareToThrowUncaughtError(error_)\
\9if not hasUncaughtError then\
\9\9hasUncaughtError = true\
\9\9firstUncaughtError = error_\
\9end\
end\
exports.onUncaughtError = prepareToThrowUncaughtError\
\
captureCommitPhaseErrorOnRoot = function(rootFiber: Fiber, sourceFiber: Fiber, error_)\
\9local errorInfo = createCapturedValue(error_, sourceFiber)\
\9-- ROBLOX deviation: parameterize method onUncaughtError to avoid circular dependency\
\9local update =\
\9\9createRootErrorUpdate(rootFiber, errorInfo, SyncLane, exports.onUncaughtError)\
\9enqueueUpdate(rootFiber, update)\
\9local eventTime = exports.requestEventTime()\
\9local root = mod.markUpdateLaneFromFiberToRoot(rootFiber, SyncLane)\
\9if root ~= nil then\
\9\9markRootUpdated(root, SyncLane, eventTime)\
\9\9ensureRootIsScheduled(root, eventTime)\
\9\9mod.schedulePendingInteractions(root, SyncLane)\
\9end\
end\
\
-- exports.captureCommitPhaseError(\
--   sourceFiber: Fiber,\
--   nearestMountedAncestor: Fiber | nil,\
--   error: mixed\
-- )\
exports.captureCommitPhaseError = function(\
\9sourceFiber: Fiber,\
\9nearestMountedAncestor,\
\9error_\
)\
\9if sourceFiber.tag == ReactWorkTags.HostRoot then\
\9\9-- Error was thrown at the root. There is no parent, so the root\
\9\9-- itself should capture it.\
\9\9captureCommitPhaseErrorOnRoot(sourceFiber, sourceFiber, error_)\
\9\9return\
\9end\
\
\9local fiber = nil\
\9if skipUnmountedBoundaries then\
\9\9fiber = nearestMountedAncestor\
\9else\
\9\9fiber = sourceFiber.return_\
\9end\
\
\9while fiber ~= nil do\
\9\9if fiber.tag == ReactWorkTags.HostRoot then\
\9\9\9captureCommitPhaseErrorOnRoot(fiber, sourceFiber, error_)\
\9\9\9return\
\9\9else\
\9\9\9if fiber.tag == ReactWorkTags.ClassComponent then\
\9\9\9\9local ctor = fiber.type\
\9\9\9\9local instance = fiber.stateNode\
\9\9\9\9if\
\9\9\9\9\9typeof(ctor.getDerivedStateFromError) == \"function\"\
\9\9\9\9\9or (\
\9\9\9\9\9\9typeof(instance.componentDidCatch) == \"function\"\
\9\9\9\9\9\9and not exports.isAlreadyFailedLegacyErrorBoundary(instance)\
\9\9\9\9\9)\
\9\9\9\9then\
\9\9\9\9\9local errorInfo = createCapturedValue(error_, sourceFiber)\
\9\9\9\9\9local update = createClassErrorUpdate(fiber, errorInfo, SyncLane)\
\9\9\9\9\9enqueueUpdate(fiber, update)\
\9\9\9\9\9local eventTime = exports.requestEventTime()\
\9\9\9\9\9local root = mod.markUpdateLaneFromFiberToRoot(fiber, SyncLane)\
\9\9\9\9\9if root ~= nil then\
\9\9\9\9\9\9markRootUpdated(root, SyncLane, eventTime)\
\9\9\9\9\9\9ensureRootIsScheduled(root, eventTime)\
\9\9\9\9\9\9mod.schedulePendingInteractions(root, SyncLane)\
\9\9\9\9\9end\
\9\9\9\9\9return\
\9\9\9\9end\
\9\9\9end\
\9\9\9fiber = fiber.return_\
\9\9end\
\9end\
end\
\
exports.pingSuspendedRoot = function(\
\9root: FiberRoot,\
\9wakeable: Wakeable,\
\9pingedLanes: Lanes\
)\
\9local pingCache = root.pingCache\
\9if pingCache ~= nil then\
\9\9-- The wakeable resolved, so we no longer need to memoize, because it will\
\9\9-- never be thrown again.\
\9\9pingCache[wakeable] = nil\
\9end\
\
\9local eventTime = exports.requestEventTime()\
\9markRootPinged(root, pingedLanes, eventTime)\
\
\9if\
\9\9workInProgressRoot == root\
\9\9and isSubsetOfLanes(workInProgressRootRenderLanes, pingedLanes)\
\9then\
\9\9-- Received a ping at the same priority level at which we're currently\
\9\9-- rendering. We might want to restart this render. This should mirror\
\9\9-- the logic of whether or not a root suspends once it completes.\
\
\9\9-- TODO: If we're rendering sync either due to Sync, Batched or expired,\
\9\9-- we should probably never restart.\
\
\9\9-- If we're suspended with delay, or if it's a retry, we'll always suspend\
\9\9-- so we can always restart.\
\9\9if\
\9\9\9workInProgressRootExitStatus == RootExitStatus.SuspendedWithDelay\
\9\9\9or workInProgressRootExitStatus == RootExitStatus.Suspended\
\9\9\9\9and includesOnlyRetries(workInProgressRootRenderLanes)\
\9\9\9\9and now() - globalMostRecentFallbackTime < FALLBACK_THROTTLE_MS\
\9\9then\
\9\9\9-- Restart from the root.\
\9\9\9mod.prepareFreshStack(root, ReactFiberLane.NoLanes)\
\9\9else\
\9\9\9-- Even though we can't restart right now, we might get an\
\9\9\9-- opportunity later. So we mark this render as having a ping.\
\9\9\9workInProgressRootPingedLanes =\
\9\9\9\9mergeLanes(workInProgressRootPingedLanes, pingedLanes)\
\9\9end\
\9end\
\
\9ensureRootIsScheduled(root, eventTime)\
\9mod.schedulePendingInteractions(root, pingedLanes)\
end\
\
function retryTimedOutBoundary(boundaryFiber: Fiber, retryLane: Lane)\
\9-- The boundary fiber (a Suspense component or SuspenseList component)\
\9-- previously was rendered in its fallback state. One of the promises that\
\9-- suspended it has resolved, which means at least part of the tree was\
\9-- likely unblocked. Try rendering again, at a new expiration time.\
\9if retryLane == ReactFiberLane.NoLane then\
\9\9retryLane = requestRetryLane(boundaryFiber)\
\9end\
\9-- TODO: Special case idle priority?\
\9local eventTime = exports.requestEventTime()\
\9local root = mod.markUpdateLaneFromFiberToRoot(boundaryFiber, retryLane)\
\9if root ~= nil then\
\9\9markRootUpdated(root, retryLane, eventTime)\
\9\9ensureRootIsScheduled(root, eventTime)\
\9\9mod.schedulePendingInteractions(root, retryLane)\
\9end\
end\
