exports.resolveRetryWakeable = function(boundaryFiber: Fiber, wakeable: Wakeable)\
\9local retryLane = ReactFiberLane.NoLane -- Default\
\9local retryCache -- : WeakSet<Wakeable> | Set<Wakeable> | nil\
\9-- ROBLOX performance: avoid always-false comapare\
\9-- if ReactFeatureFlags.enableSuspenseServerRenderer then\
\9--   if boundaryFiber.tag == ReactWorkTags.SuspenseComponent then\
\9--       retryCache = boundaryFiber.stateNode\
\9--       local suspenseState: nil | SuspenseState = boundaryFiber.memoizedState\
\9--       if suspenseState ~= nil then\
\9--         -- ROBLOX TODO: Remove Luau narrowing workaround\
\9--         retryLane = (suspenseState :: SuspenseState).retryLane\
\9--       end\
\9--     elseif boundaryFiber.tag == ReactWorkTags.SuspenseListComponent then\
\9--       retryCache = boundaryFiber.stateNode\
\9--     else\
\9--       invariant(\
\9--         false,\
\9--         'Pinged unknown suspense boundary type. ' ..\
\9--           'This is probably a bug in React.'\
\9--       )\
\9--   end\
\9-- else\
\9retryCache = boundaryFiber.stateNode\
\9-- end\
\
\9if retryCache ~= nil then\
\9\9-- The wakeable resolved, so we no longer need to memoize, because it will\
\9\9-- never be thrown again.\
\9\9retryCache:delete(wakeable)\
\9end\
